window.TADABBUR_ZUKHRUF = {"_meta":{"description":"تدبّر سورة الزخرف (٤٣) — سورةٌ مكّيّةٌ من الحواميم. تُسمّى الزخرفَ لذكرِ زخرفِ الدنيا فيها. محورُها تعظيمُ القرآنِ العربيّ، والردُّ على المشركين في دعوى البناتِ لله وعبادةِ الملائكة، وقصصُ إبراهيمَ وموسى وعيسى، وأنّ الدنيا متاعٌ زائلٌ لا وزنَ لها عند الله، وأنّ الأخلّاءَ يومَ القيامةِ أعداءٌ إلا المتّقين. فيها «وإنه في أم الكتاب لدينا لعلي حكيم»، و«ولولا أن يكون الناس أمة واحدة لجعلنا لمن يكفر بالرحمن... سقفا من فضة»، و«الأخلاء يومئذ بعضهم لبعض عدو إلا المتقين»، و«يا عباد لا خوف عليكم اليوم ولا أنتم تحزنون».","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":43,"name":"الزخرف","total_ayahs":89,"audio":[],"passages":[{"title":"تعظيمُ القرآنِ العربيِّ وعلوّه، ودوامُ التذكير، وهلاكُ المستهزئين","range":[1,8],"theme":"القسمُ بالكتابِ المبين، وأنّ الله جعله قرآنًا عربيًّا للتعقّل، وأنه في أمِّ الكتابِ عليٌّ حكيم، وأنّ الله لا يترك تذكيرَ المسرفين رحمةً بهم، وكثرةُ الأنبياءِ في الأوّلين وأنّ المكذّبين استهزؤوا بهم فأهلك الله أشدَّ منهم بطشًا","verses":[{"n":1,"reflection":{"text":"«حم» — حروفٌ مقطّعةٌ افتُتِحت بها السورةُ، من المتشابهِ الذي استأثر الله بعلمه، ويُشار بها إلى إعجازِ القرآن؛ ففي هذا تنبيهٌ على عظمةِ القرآن؛ فسلّم لله فيما استأثر بعلمه، وتدبّر ما بيّنه، فالتسليمُ فيما لم تعلم من صفاتِ الراسخين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله فيما استأثر بعلمه، والتدبّرُ لما بيّن."},"action":{"text":"اعلم أنّ سورةَ الزخرف افتُتِحت بـ«حم» من الحروفِ المقطّعةِ التي هي من المتشابهِ الذي استأثر الله بعلمِ المرادِ منه «حم»؛ وأصحُّ ما قيل فيها الإشارةُ إلى إعجازِ القرآن المؤلَّفِ من جنسِ هذه الحروف؛ فسلّم لما استأثر الله بعلمه من المتشابه؛ وتدبّر واعمل بما بيّنه لك من المحكم؛ فالراسخون في العلمِ يقولون آمنّا به كلٌّ من عند ربنا؛ فاجعل تسليمك لله فيما لم تعلم علامةَ إيمانك؛ فبالتسليمِ والعملِ تُنال الهداية."}},{"n":2,"reflection":{"text":"«والكتاب المبين» — أقسم الله بالكتابِ الواضحِ البيّنِ (القرآن)؛ ففي هذا تعظيمُ شأنِ القرآنِ وبيانُ وضوحه؛ فعظّم القرآنَ الذي أقسم الله به ووصفه بالبيان، وتدبّر بيانه، فالقرآنُ كتابٌ مبينٌ واضح، فاعتنِ به تلاوةً وتدبّرًا وعملًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ المبينِ والاعتناءُ به تلاوةً وتدبّرًا."},"action":{"text":"تأمّل قسمَ الله بكتابه: والكتابِ المبينِ الواضحِ في ألفاظه ومعانيه، البيّنِ للحقِّ والهدى، المُظهِرِ لكلِّ ما يحتاجه العباد «والكتاب المبين»؛ ففي هذا تعظيمُ شأنِ القرآن، وبيانُ وضوحه وبيانه؛ فأقسم الله به تعظيمًا لشأنه؛ فعظّم القرآنَ الذي أقسم الله به؛ فهو كتابٌ مبينٌ واضحُ الدلالة، بيّنُ الأحكامِ والأخبار؛ فتدبّر بيانه، وتأمّل معانيه؛ واعتنِ به تلاوةً وتدبّرًا وعملًا وتحكيمًا؛ فمن عظّم القرآنَ وأقبل عليه اهتدى به؛ فاجعل للقرآنِ المبينِ في قلبك مكانته اللائقة؛ فبتعظيمِ القرآنِ والعملِ به تُنال الهدايةُ والسعادة."}},{"n":3,"reflection":{"text":"«إنا جعلناه قرآنا عربيا لعلكم تعقلون» — إنا جعلناه قرآنًا عربيًّا بلسانٍ عربيٍّ مبين لعلّكم تعقلون معانيه؛ ففي هذا بيانُ حكمةِ إنزالِ القرآنِ عربيًّا للتعقّل؛ فاعقل معانيَ القرآنِ وتدبّرها، فالقرآنُ أُنزِل عربيًّا لتعقله، فأعمل عقلك في فهمِ القرآنِ والعملِ به، فالغايةُ من نزوله التعقّلُ والتدبّر.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إعمالُ العقلِ في فهمِ القرآنِ العربيِّ وتدبّرِه."},"action":{"text":"تأمّل حكمةَ إنزالِ القرآنِ عربيًّا: إنا جعلنا هذا الكتابَ قرآنًا عربيًّا بلسانٍ عربيٍّ مبينٍ واضح، لعلّكم أيها العربُ تعقلون معانيه وتفهمونها وتنتفعون بها «إنا جعلناه قرآنا عربيا لعلكم تعقلون»؛ ففي هذا بيانُ حكمةِ إنزالِ القرآنِ بلسانٍ عربيٍّ مبين، وهي أن يعقله الناسُ ويفهموه؛ فالغايةُ من إنزالِ القرآنِ عربيًّا واضحًا التعقّلُ والتدبّرُ والفهمُ والعمل؛ فاعقل معانيَ القرآنِ وتدبّرها؛ وأعمل عقلك في فهمه والعملِ به؛ فما أُنزِل القرآنُ ليُهجَر أو يُتلى بلا تدبّر؛ بل أُنزِل ليُعقَل ويُفهَم ويُعمَل به؛ أفلا يتدبّرون القرآن؛ كتابٌ أنزلناه إليك مبارك ليدبّروا آياته؛ فلا تكن ممّن يقرأ القرآنَ بلا تعقّلٍ ولا تدبّر؛ بل اقرأه بتعقّلٍ وتأمّلٍ وفهم؛ فمن عقل القرآنَ وتدبّره انتفع به واهتدى؛ فاجعل غايتك من القرآنِ التعقّلَ والتدبّرَ والعمل."}},{"n":4,"reflection":{"text":"«وإنه في أم الكتاب لدينا لعلي حكيم» — وإنّ القرآنَ في اللوحِ المحفوظِ عندنا لعليُّ القدرِ حكيمٌ محكم؛ ففي هذا بيانُ علوِّ منزلةِ القرآنِ وإحكامه؛ فعظّم القرآنَ العليَّ الحكيمَ، فهو في أعلى منزلةٍ عند الله، فاجعل له في قلبك مكانةً تليق بعلوّه، فالقرآنُ عليٌّ حكيمٌ محفوظٌ عند الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ العليِّ الحكيم، وإدراكُ علوِّ منزلته عند الله."},"action":{"text":"تأمّل علوَّ منزلةِ القرآن: وإنّ هذا القرآنَ في أمِّ الكتابِ — اللوحِ المحفوظِ الذي هو أصلُ الكتبِ — لدينا وعندنا، لعليُّ القدرِ والمنزلة، حكيمٌ محكمٌ في آياته وأحكامه، لا يأتيه الباطل «وإنه في أم الكتاب لدينا لعلي حكيم»؛ ففي هذا بيانُ علوِّ منزلةِ القرآنِ عند الله، وإحكامه؛ فالقرآنُ مثبتٌ في اللوحِ المحفوظِ عند الله؛ وهو عليُّ القدرِ رفيعُ المنزلة، حكيمٌ محكمُ الآياتِ والأحكام؛ فعظّم القرآنَ العليَّ الحكيمَ في قلبك؛ واعلم أنه في أعلى منزلةٍ عند الله، محفوظٌ في اللوحِ المحفوظ؛ فاجعل له في قلبك مكانةً تليق بعلوّه وإحكامه؛ فمن عرف علوَّ منزلةِ القرآنِ عند الله عظّمه في قلبه؛ فالقرآنُ كلامُ الله العليُّ الحكيم؛ فلا تستهن به، ولا تهجره، ولا تعرض عنه؛ بل عظّمه، وأقبل عليه، واعمل به؛ فبتعظيمِ القرآنِ العليِّ الحكيمِ يُنتفَع به ويُهتَدى بهديه."}},{"n":5,"reflection":{"text":"«أفنضرب عنكم الذكر صفحا أن كنتم قوما مسرفين» — أفنترك إنزالَ القرآنِ وتذكيركم به إعراضًا عنكم لأنكم قومٌ مسرفون في الكفر؟ لا، بل نستمرّ في تذكيركم؛ ففي هذا بيانُ رحمةِ الله في استمرارِ التذكيرِ رغمَ الإسراف؛ فاعلم أنّ الله لا يترك تذكيرَ عباده رحمةً بهم، فاغتنم تذكيرَ الله ولا تسرف في الإعراض، فمن رحمةِ الله دوامُ التذكير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اغتنامُ تذكيرِ الله، وإدراكُ رحمتِه في دوامِ التذكير."},"action":{"text":"تأمّل رحمةَ الله في دوامِ التذكير: أفنترك ونصرف عنكم الذكرَ — القرآنَ والتذكيرَ به — صفحًا وإعراضًا، ونمسك عن دعوتكم وتذكيركم، لأنكم قومٌ مسرفون في الكفرِ والإعراض؟ لا، بل نستمرّ في تذكيركم وإنزالِ القرآنِ رحمةً بكم وإقامةً للحجّة «أفنضرب عنكم الذكر صفحا أن كنتم قوما مسرفين»؛ ففي هذا بيانُ رحمةِ الله في استمرارِ التذكيرِ والدعوةِ رغمَ إسرافِ العبادِ في الكفر؛ فلم يترك الله تذكيرهم مع إسرافهم؛ بل استمرّ في دعوتهم رحمةً بهم؛ فاعلم أنّ الله لا يترك تذكيرَ عباده وإن أسرفوا، رحمةً بهم وإقامةً للحجّة؛ فاغتنم تذكيرَ الله ودعوته لك عبر القرآن؛ ولا تسرف في الإعراضِ والكفرِ فتُحرَم بركةَ التذكير؛ فمن رحمةِ الله بك أن يذكّرك ويدعوك مع تقصيرك؛ فقابل تذكيرَ الله بالاستجابةِ والإقبال، لا بالإعراضِ والإسراف؛ فاغتنم كلَّ تذكيرٍ من الله لك؛ فمن اغتنم تذكيرَ الله واتّعظ به نجا، ومن أعرض عنه وأسرف في الكفرِ هلك."}},{"n":6,"reflection":{"text":"«وكم أرسلنا من نبي في الأولين» — وكثيرًا من الأنبياءِ أرسلنا في الأممِ الأولين؛ ففي هذا بيانُ كثرةِ الرسلِ ورحمةِ الله بإرسالهم؛ فاعلم أنّ الله أرسل الرسلَ كثيرين رحمةً بالعباد، فآمن بجميعِ الرسل، واشكر نعمةَ الله بإرسالهم، فإرسالُ الرسلِ من أعظمِ رحمةِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بجميعِ الرسل، وشكرُ نعمةِ الله بإرسالهم."},"action":{"text":"تأمّل كثرةَ الرسلِ ورحمةَ الله: وكم أرسلنا من نبيٍّ في الأممِ الأولين، أرسلناهم رحمةً بالعبادِ وهدايةً لهم «وكم أرسلنا من نبي في الأولين»؛ ففي هذا بيانُ كثرةِ الأنبياءِ الذين أرسلهم الله في الأممِ السابقة؛ فما ترك الله أمّةً بلا نذير؛ وإن من أمّةٍ إلا خلا فيها نذير؛ فاعلم أنّ الله أرسل الرسلَ كثيرين رحمةً بالعبادِ وإقامةً للحجّة؛ فآمن بجميعِ رسلِ الله، من ذُكِر منهم ومن لم يُذكَر؛ واشكر نعمةَ الله بإرسالِ الرسلِ لهدايةِ العباد؛ فإرسالُ الرسلِ من أعظمِ رحمةِ الله بخلقه؛ فبهم عرف الناسُ ربهم ودينهم وطريقَ نجاتهم؛ فاحمد الله أن أرسل إليك خاتمَ الأنبياءِ محمدًا ﷺ؛ واتّبع ما جاء به؛ فمن آمن بالرسلِ واتّبعهم نجا؛ فاجعل الإيمانَ بالرسلِ وشكرَ نعمةِ إرسالهم من إيمانك؛ فهم رحمةُ الله بعباده."}},{"n":7,"reflection":{"text":"«وما يأتيهم من نبي إلا كانوا به يستهزئون» — وما يأتي الأممَ نبيٌّ إلا استهزؤوا به؛ ففي هذا تسليةُ النبيِّ بأنّ الاستهزاءَ بالرسلِ قديم؛ فلا يحزنك استهزاءُ المستهزئين بالحقّ، فقد استُهزِئ بالرسلِ قبلك، فاصبر على أذاهم، فالاستهزاءُ بالحقِّ سنّةُ المكذّبين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الاستهزاءِ بالحق، وإدراكُ أنه سنّةُ المكذّبين."},"action":{"text":"تأمّل تسليةَ الله لنبيّه: وما يأتي هذه الأممَ من نبيٍّ يدعوهم إلى الحقِّ إلا كانوا به يستهزئون ويسخرون «وما يأتيهم من نبي إلا كانوا به يستهزئون»؛ ففي هذا تسليةٌ للنبيِّ ﷺ، وبيانٌ أنّ الاستهزاءَ بالرسلِ سنّةٌ قديمةٌ في الأممِ المكذّبة؛ فما من نبيٍّ إلا استُهزِئ به؛ يا حسرةً على العباد ما يأتيهم من رسولٍ إلا كانوا به يستهزئون؛ فلا يحزنك يا محمدُ استهزاءُ المستهزئين بك وبالحقّ؛ فقد استُهزِئ بالرسلِ من قبلك فصبروا؛ فتأسَّ بهم في الصبرِ على الاستهزاءِ والأذى؛ ولقد استُهزِئ برسلٍ من قبلك؛ فاصبر على أذى المستهزئين وسخريتهم؛ ولا يصدّنّك ذلك عن الحق؛ فالاستهزاءُ بالحقِّ وأهله سنّةُ المكذّبين في كلِّ زمان؛ فلا يهولنّك ذلك؛ بل امضِ في الحقِّ صابرًا محتسبًا؛ فالعاقبةُ للحقِّ وأهله، والخزيُ للمستهزئين؛ فاصبر، ولا تكترث باستهزائهم؛ فإنّ الله كافيك المستهزئين."}},{"n":8,"reflection":{"text":"«فأهلكنا أشد منهم بطشا ومضى مثل الأولين» — فأهلكنا أممًا أشدَّ من هؤلاء قوّةً وبطشًا، ومضت أمثالُ عقوباتِ الأوّلين؛ ففي هذا وعيدُ المستهزئين بعذابِ من هو أقوى منهم؛ فاحذر الاستهزاءَ والتكذيبَ الذي أهلك الأممَ الأقوى، ولا تغترّ بقوّتك، فالقوّةُ لا تدفع عذابَ الله، فاتّعظ بمن قبلك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بهلاكِ الأممِ الأقوى، وعدمُ الاغترارِ بالقوّة."},"action":{"text":"تأمّل وعيدَ المستهزئين: فأهلكنا أممًا كانوا أشدَّ من هؤلاء المشركين قوّةً وبطشًا وأخذًا، بسببِ استهزائهم وتكذيبهم؛ ومضى وسبق مثلُ الأوّلين — أي سُنّةُ الله في إهلاكهم، أو صفةُ عقوباتهم — عبرةً للآخرين «فأهلكنا أشد منهم بطشا ومضى مثل الأولين»؛ ففي هذا وعيدُ المستهزئين المكذّبين بعذابِ الأممِ الأقوى قبلهم؛ فإذا كان الله أهلك من هو أشدُّ منهم قوّةً، فكيف بهؤلاء الضعفاء؟ فاحذر الاستهزاءَ بالحقِّ والتكذيبَ الذي أهلك الأممَ الأقوى والأشدَّ بطشًا؛ ولا تغترّ بقوّتك ومالك وجاهك؛ فإنّ القوّةَ والبطشَ لا يدفعان عذابَ الله عمّن استحقّه؛ فكم من أمّةٍ قويّةٍ باطشةٍ أهلكها الله بذنوبها؛ فاتّعظ بمن قبلك من الأممِ الهالكة؛ ولا تسلك سبيلهم في الاستهزاءِ والتكذيب؛ فمن اتّعظ بعاقبةِ المكذّبين سلم، ومن اغترّ بقوّته وكذّب هلك؛ فاجعل من مصارعِ الأممِ الأقوى عبرةً تحملك على الإيمانِ وترْكِ الاستهزاء."}}]},{"title":"إقرارُ المشركين بالخالقِ ونعمُه، وذكرُ النعمةِ عند الركوبِ والرجوعِ إلى الله","range":[9,14],"theme":"إقرارُ المشركين بأنّ العزيزَ العليمَ خلق السماواتِ والأرض، وتعدادُ نعمِه في تمهيدِ الأرضِ وجعلِ السبلِ وإنزالِ الماءِ وإحياءِ الأرضِ دليلًا على البعث، وخلقِ الأزواجِ وتسخيرِ الفلكِ والأنعام، وتعليمُ ذكرِ النعمةِ والتسبيحِ عند الركوبِ وتذكّرِ الرجوعِ إلى الله","verses":[{"n":9,"reflection":{"text":"«ولئن سألتهم من خلق السماوات والأرض ليقولن خلقهن العزيز العليم» — ولئن سألت المشركين من خلق السماواتِ والأرض ليقولنّ: خلقهنّ العزيزُ العليم؛ ففي هذا إقرارُ المشركين بالخالقِ وإلزامهم بتوحيدِ العبادة؛ فاعلم أنّ من أقرّ بأنّ الله الخالقُ يلزمه أن يعبده وحده، فوحّد الخالقَ العزيزَ العليمَ في العبادةِ كما تفرّد بالخلق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الخالقِ العزيزِ العليمِ في العبادة، كما تفرّد بالخلق."},"action":{"text":"تأمّل إقرارَ المشركين بالخالق: ولئن سألت المشركين من خلق السماواتِ والأرض ليقولنّ مقرّين: خلقهنّ العزيزُ الغالبُ، العليمُ بكلِّ شيء «ولئن سألتهم من خلق السماوات والأرض ليقولن خلقهن العزيز العليم»؛ ففي هذا إقرارُ المشركين بأنّ الله هو الخالقُ، وإلزامهم بتوحيدِ العبادةِ الذي أنكروه؛ فهم يقرّون بأنّ الله الخالقُ الرازقُ المدبّر، ومع ذلك يشركون به في العبادة؛ فاعلم أنّ من أقرّ بأنّ الله هو الخالقُ الرازقُ المدبّر يلزمه أن يعبده وحده؛ فالإقرارُ بالربوبيةِ يستلزم توحيدَ الألوهيةِ والعبادة؛ فوحّد الخالقَ العزيزَ العليمَ في العبادةِ كما تفرّد بالخلقِ والتدبير؛ فأفرده بالعبادةِ كما أفردته بالخلق؛ فكيف تعبد مع الخالقِ غيره؟ وكيف تصرف العبادةَ لمن لم يخلق؟ فاعبد الله الخالقَ وحده؛ ولا تشرك به شيئًا من العبادة؛ فمن أقرّ بأنّ الله الخالقُ ثم أشرك في العبادةِ فقد ناقض نفسه؛ فحقّق التوحيدَ الكامل: توحيدَ الربوبيةِ والألوهية؛ فوحّد الخالقَ في عبادتك، وأخلص له الدين."}},{"n":10,"reflection":{"text":"«الذي جعل لكم الأرض مهدا وجعل لكم فيها سبلا لعلكم تهتدون» — الذي جعل لكم الأرضَ فراشًا ممهّدًا، وجعل لكم فيها طرقًا لتهتدوا في أسفاركم؛ ففي هذا تعدادُ نعمِ الله في الأرض؛ فتأمّل نعمةَ الله في تمهيدِ الأرضِ وجعلِ السبل، واشكرها، فمن مهّد لك الأرضَ وجعل فيها سبلًا يستحقّ العبادةَ والشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الله في تمهيدِ الأرضِ وجعلِ السبل، وتوحيدُ المنعم."},"action":{"text":"تأمّل نعمَ الله في الأرض: الله الذي جعل لكم الأرضَ مهدًا وفراشًا ممهّدًا ومستقرًّا تعيشون عليها وتستقرّون؛ وجعل لكم فيها سبلًا وطرقًا بين الجبالِ والأوديةِ والبلدان لعلّكم تهتدون بها في أسفاركم إلى مقاصدكم «الذي جعل لكم الأرض مهدا وجعل لكم فيها سبلا لعلكم تهتدون»؛ ففي هذا تعدادُ نعمِ الله في تمهيدِ الأرضِ وجعلِ السبلِ فيها؛ فمن مهّد لك الأرضَ لتستقرّ عليها؟ ومن جعل فيها الطرقَ لتهتديَ في أسفارك؟ إنه الله؛ فتأمّل نعمةَ الله في تمهيدِ الأرضِ وتيسيرِ العيشِ عليها، وجعلِ السبلِ للاهتداء؛ واشكر الله على هذه النعم؛ فمن مهّد الأرضَ وجعل فيها السبلَ يستحقّ العبادةَ والشكرَ والتوحيد؛ فاستعمل نعمَ الله في طاعته؛ فمن تأمّل نعمَ الله في الأرضِ شكرها ووحّد المنعم؛ فاجعل تأمّلك في نعمِ الله سبيلًا لشكره وعبادته؛ فهو الذي مهّد لك الأرضَ وجعل فيها السبل؛ فاشكره ووحّده."}},{"n":11,"reflection":{"text":"«والذي نزل من السماء ماء بقدر فأنشرنا به بلدة ميتا كذلك تخرجون» — والذي نزّل من السماءِ ماءً بقدرٍ معلوم، فأحيينا به بلدةً ميتة، كذلك تُخرَجون من قبوركم؛ ففي هذا نعمةُ الماءِ والاستدلالُ بإحياءِ الأرضِ على البعث؛ فتأمّل إحياءَ الأرضِ بالماء، فمن أحياها يحييك بعد موتك، فأيقن بالبعثِ واشكر نعمةَ الماء، فالقادرُ على إحياءِ الأرضِ قادرٌ على بعثك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الماء، واليقينُ بالبعثِ استدلالًا بإحياءِ الأرض."},"action":{"text":"تأمّل نعمةَ الماءِ ودلالتَه على البعث: والذي نزّل من السماءِ ماءً — المطر — بقدرٍ معلومٍ لا يزيد فيغرق ولا ينقص فيعطش، بحكمته؛ فأنشرنا وأحيينا به بلدةً ميتةً هامدةً لا نباتَ فيها فأخرجنا نباتها؛ كذلك — كإحياءِ الأرضِ الميتة — تُخرَجون من قبوركم أحياءً يومَ البعث «والذي نزل من السماء ماء بقدر فأنشرنا به بلدة ميتا كذلك تخرجون»؛ ففي هذا نعمةُ إنزالِ الماءِ بقدر، والاستدلالُ بإحياءِ الأرضِ الميتةِ على البعث؛ فتأمّل نعمةَ الله في إنزالِ الماءِ بقدرٍ يصلح به العبادُ والبلاد؛ واشكر هذه النعمةَ العظيمة؛ وتأمّل إحياءَ الأرضِ الميتةِ بالماءِ فتخضرّ وتنبت؛ فمن أحيا الأرضَ الميتةَ قادرٌ على أن يحييك بعد موتك ويخرجك من قبرك؛ فالقادرُ على إحياءِ الأرضِ قادرٌ على البعث؛ فأيقن بالبعثِ الذي هو حق؛ واستعدّ له بالإيمانِ والعملِ الصالح؛ فاجعل من نعمةِ الماءِ وإحياءِ الأرضِ دليلًا على شكرِ الله واليقينِ بالبعث؛ فمن تأمّلهما شكر ووحّد وأيقن بالبعث."}},{"n":12,"reflection":{"text":"«والذي خلق الأزواج كلها وجعل لكم من الفلك والأنعام ما تركبون» — والذي خلق الأصنافَ كلَّها من كلِّ شيء، وجعل لكم من السفنِ والأنعامِ ما تركبون؛ ففي هذا تعدادُ نعمةِ خلقِ الأزواجِ وتسخيرِ المراكب؛ فتأمّل نعمةَ الله في خلقِ الأصنافِ وتسخيرِ ما تركب، واشكرها، فمن خلق الأزواجَ وسخّر المراكبَ يستحقّ العبادةَ والشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ خلقِ الأزواجِ وتسخيرِ المراكب، وتوحيدُ الخالق."},"action":{"text":"تأمّل نعمَ الله في الخلقِ والتسخير: والذي خلق الأزواجَ كلَّها — أي الأصنافَ والأنواعَ كلَّها من الحيوانِ والنباتِ وغيرها، أو الذكرَ والأنثى من كلِّ شيء؛ وجعل لكم من الفلكِ — السفن — والأنعامِ — الإبلِ ونحوها — ما تركبون في البرِّ والبحر «والذي خلق الأزواج كلها وجعل لكم من الفلك والأنعام ما تركبون»؛ ففي هذا تعدادُ نعمةِ خلقِ الأزواجِ والأصناف، وتسخيرِ المراكبِ من الفلكِ والأنعام؛ فمن خلق هذه الأصنافَ المتنوّعة؟ ومن سخّر لك السفنَ والأنعامَ لتركبها وتحمل عليها؟ إنه الله؛ فتأمّل نعمةَ الله في خلقِ الأصنافِ المتنوّعة، وتسخيرِ ما تركبه في البرِّ والبحر؛ واشكر هذه النعم؛ فمن خلق الأزواجَ وسخّر المراكبَ يستحقّ العبادةَ والشكرَ والتوحيد؛ سبحان الذي سخّر لنا هذا وما كنّا له مقرنين؛ فاستعمل هذه النعمَ في طاعةِ الله؛ فمن تأمّل نعمَ الله شكرها ووحّد المنعم؛ فاشكر الله على خلقِ الأزواجِ وتسخيرِ المراكب."}},{"n":13,"reflection":{"text":"«لتستووا على ظهوره ثم تذكروا نعمة ربكم إذا استويتم عليه وتقولوا سبحان الذي سخر لنا هذا وما كنا له مقرنين» — لتستقرّوا على ظهورِ المراكب، ثم تذكروا نعمةَ ربّكم إذا استويتم عليها، وتقولوا: سبحان الذي سخّر لنا هذا وما كنّا له مطيقين؛ ففي هذا تعليمُ ذكرِ النعمةِ والتسبيحِ عند الركوب؛ فاذكر نعمةَ الله عند ركوبك، وسبّحه، فمن استعمل النعمةَ في ذكرِ الله فقد شكرها، فقل دعاءَ الركوبِ شكرًا لله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"ذكرُ نعمةِ الله والتسبيحُ عند الركوب، شكرًا لها."},"action":{"text":"تأمّل تعليمَ الله لذكرِ النعمةِ عند الركوب: سخّر لكم هذه المراكبَ لتستووا وتستقرّوا على ظهورها؛ ثم تذكروا نعمةَ ربّكم عليكم بهذا التسخيرِ إذا استويتم واستقررتم عليها؛ وتقولوا: سبحان الذي سخّر لنا هذا المركبَ وذلّله، وما كنّا له مقرنين — أي مطيقين ضابطين لولا تسخيرُ الله «لتستووا على ظهوره ثم تذكروا نعمة ربكم إذا استويتم عليه وتقولوا سبحان الذي سخر لنا هذا وما كنا له مقرنين»؛ ففي هذا تعليمُ ذكرِ نعمةِ الله والتسبيحِ عند الركوب؛ فعلّمنا الله أن نذكر نعمته ونسبّحه عند ركوبِ ما سخّره لنا؛ فاذكر نعمةَ الله عليك عند ركوبك دابّتك أو سيّارتك أو سفينتك أو طائرتك؛ وسبّح الله وقل دعاءَ الركوب: سبحان الذي سخّر لنا هذا وما كنّا له مقرنين وإنا إلى ربنا لمنقلبون؛ فكان النبيُّ ﷺ إذا استوى على دابّته كبّر ثلاثًا ثم قال هذا الدعاء؛ فمن استعمل النعمةَ في ذكرِ الله وتسبيحه فقد شكرها؛ فاجعل ركوبك مذكّرًا بنعمةِ الله، مقرونًا بذكره وتسبيحه؛ فبذكرِ النعمةِ عند استعمالها تُشكَر النعمة، وتدوم البركة."}},{"n":14,"reflection":{"text":"«وإنا إلى ربنا لمنقلبون» — وإنا إلى ربّنا لراجعون بعد الموت؛ ففي هذا تذكيرٌ بالرجوعِ إلى الله في دعاءِ الركوب؛ فتذكّر رجوعك إلى الله عند سفرك وركوبك، فكلُّ سفرٍ يذكّرك بالسفرِ الأكبرِ إلى الله، فاستعدّ للرجوعِ إليه، فإنا إلى ربّنا لمنقلبون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تذكّرُ الرجوعِ إلى الله عند السفر، والاستعدادُ للقاء."},"action":{"text":"تأمّل ختامَ دعاءِ الركوب: وإنا إلى ربّنا لمنقلبون وراجعون بعد الموتِ للحسابِ والجزاء «وإنا إلى ربنا لمنقلبون»؛ ففي هذا تذكيرٌ بالرجوعِ إلى الله في دعاءِ الركوب؛ فختم الله دعاءَ الركوبِ بتذكّرِ الرجوعِ إليه؛ فكما نسافر في الدنيا ونركب المراكب، فإنا مسافرون إلى الله راجعون إليه؛ فتذكّر رجوعك إلى الله عند سفرك وركوبك؛ فكلُّ سفرٍ في الدنيا يذكّرك بالسفرِ الأكبرِ إلى الله والدارِ الآخرة؛ فكما تتزوّد لسفرِ الدنيا، تزوّد لسفرِ الآخرة بالتقوى والعملِ الصالح؛ وتزوّدوا فإنّ خيرَ الزادِ التقوى؛ فاستعدّ للرجوعِ إلى الله والانقلابِ إليه؛ فإليه المصير؛ فمن تذكّر رجوعه إلى الله استعدّ له بالعملِ الصالح؛ فاجعل من ركوبك وسفرك مذكّرًا برجوعك إلى الله؛ فقل: وإنا إلى ربنا لمنقلبون؛ متذكّرًا الآخرةَ والحساب؛ فبتذكّرِ الرجوعِ إلى الله يستقيم العملُ ويحسن الاستعداد؛ فتزوّد لسفرك الأكبرِ إلى ربك."}}]},{"title":"دعوى البناتِ لله وذمُّها، وعبادةُ الملائكةِ والقولُ على الغيبِ بلا علم","range":[15,20],"theme":"جعلُ المشركين لله جزءًا من عباده وأنّ الإنسانَ كفور، وإنكارُ نسبةِ البناتِ إلى الله مع كراهتهم لها حتى يسودّ وجه أحدهم، وجعلُهم الملائكةَ إناثًا بلا علمٍ وأنّ شهادتهم ستُكتَب، واحتجاجُهم بالقدرِ على عبادةِ الملائكةِ وأنه ظنٌّ بلا علم","verses":[{"n":15,"reflection":{"text":"«وجعلوا له من عباده جزءا إن الإنسان لكفور مبين» — وجعل المشركون لله جزءًا من عباده (بزعمهم أنّ الملائكةَ بناتُ الله)، إنّ الإنسانَ لكفورٌ بيّنُ الكفران؛ ففي هذا ذمُّ نسبةِ الولدِ إلى الله وكفرانِ الإنسان؛ فنزّه الله عن الولدِ والجزء، واحذر كفرانَ النعمة، فمن نسب لله ولدًا فقد كفر، فوحّد الله ونزّهه واشكر نعمه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن الولد، والحذرُ من كفرانِ الإنسان."},"action":{"text":"تأمّل ذمَّ الله للمشركين: وجعل المشركون لله جزءًا وبعضًا من عباده، بزعمهم أنّ الملائكةَ بناتُ الله — والولدُ جزءٌ من والده؛ إنّ الإنسانَ لكفورٌ بيّنُ الكفران، ظاهرُ الجحودِ لنعمِ الله «وجعلوا له من عباده جزءا إن الإنسان لكفور مبين»؛ ففي هذا ذمُّ نسبةِ الولدِ والجزءِ إلى الله، وبيانُ كفرانِ الإنسانِ الظاهر؛ فنسبتهم الولدَ إلى الله من أعظمِ الكفرانِ والجحود؛ فنزّه الله عن الولدِ والجزءِ والصاحبةِ والشريك؛ فهو الأحدُ الصمدُ الذي لم يلد ولم يولد؛ فكيف يكون له جزءٌ أو ولدٌ من عباده؟ فالكلُّ عبيدٌ له مخلوقون؛ إن كلُّ من في السماواتِ والأرضِ إلا آتي الرحمنِ عبدًا؛ فنزّه الله في قلبك عن كلِّ ما لا يليق به؛ واحذر كفرانَ نعمِ الله وجحودها؛ فالإنسانُ لكفورٌ مبين إن لم يعصمه الله؛ فاشكر نعمَ الله ولا تكفرها؛ ووحّد الله ونزّهه عن الولدِ والجزء؛ فمن وحّد الله ونزّهه وشكر نعمه فقد أدّى حقّه؛ فاجعل قلبك موحّدًا منزّهًا شاكرًا، لا مشركًا كفورًا."}},{"n":16,"reflection":{"text":"«أم اتخذ مما يخلق بنات وأصفاكم بالبنين» — أاتّخذ الله لنفسه البناتِ مما يخلق، وخصّكم بالبنين؟ ففي هذا إنكارُ نسبةِ البناتِ إلى الله؛ فتأمّل تناقضَ المشركين: ينسبون لله ما يكرهون لأنفسهم، فنزّه الله عن الولدِ ذكرًا كان أو أنثى، ولا تنسب إليه ما لا يليق بجلاله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن الولد، والحذرُ من نسبةِ ما لا يليق به."},"action":{"text":"تأمّل إنكارَ الله على المشركين: أاتّخذ الله لنفسه من مخلوقاته البناتِ — بزعمهم أنّ الملائكةَ بناتُ الله — وخصّكم واصطفاكم بالبنين الذين تحبّونهم؟ «أم اتخذ مما يخلق بنات وأصفاكم بالبنين»؛ ففي هذا إنكارٌ شديدٌ على نسبةِ البناتِ إلى الله؛ فانظر إلى تناقضِ المشركين وسفهِ عقولهم: ينسبون إلى الله البناتِ اللاتي يكرهونها لأنفسهم، ويجعلون لأنفسهم البنين الذين يحبّونهم؛ فينسبون إلى الله ما يأنفون منه ويكرهونه؛ ألكم الذكرُ وله الأنثى تلك إذًا قسمةٌ ضيزى؛ فنزّه الله عن الولدِ أصلًا، ذكرًا كان أو أنثى؛ فهو الغنيُّ المنزّهُ عن الولدِ والحاجةِ إليه؛ فلا تنسب إلى الله ما لا يليق بجلالِه وكماله؛ فهو المنزّهُ عن مشابهةِ خلقه؛ ليس كمثله شيء؛ فاعرف ربك بأسمائه الحسنى وصفاته العلى؛ ونزّهه عن كلِّ نقصٍ وعيبٍ وولد؛ فمن عرف عظمةَ الله نزّهه عن كلِّ ما لا يليق به؛ فعظّم ربك، ونزّهه، وأخلص له التوحيد."}},{"n":17,"reflection":{"text":"«وإذا بشر أحدهم بما ضرب للرحمن مثلا ظل وجهه مسودا وهو كظيم» — وإذا بُشِّر أحدهم بالأنثى التي نسبها إلى الرحمن، اسودّ وجهه من الغمِّ وامتلأ حزنًا؛ ففي هذا فضحُ تناقضِ المشركين؛ فتأمّل قبحَ من ينسب إلى الله ما يسوءه ويكرهه، فنزّه الله عمّا لا يرضاه لنفسه، ولا تنسب إليه ما تكرهه، فالمشركون يكرهون لأنفسهم ما ينسبونه لله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عمّا يُكرَه، وإدراكُ تناقضِ من ينسب إليه ما يكرهه."},"action":{"text":"تأمّل فضحَ الله لتناقضِ المشركين: وإذا بُشِّر أحدهم بالأنثى — التي ضربها ونسبها للرحمن، أي البنت — ظلّ وجهه مسودًّا من الغمِّ والكآبة، وهو كظيمٌ ممتلئٌ حزنًا وغيظًا يكظمه؛ فكيف ينسبون إلى الله ما يسوءهم ويسودّ وجوههم إذا بُشِّروا به؟ «وإذا بشر أحدهم بما ضرب للرحمن مثلا ظل وجهه مسودا وهو كظيم»؛ ففي هذا فضحُ تناقضِ المشركين وقبحِ فعلهم؛ فهم يكرهون البناتِ أشدَّ الكراهية، حتى يسودّ وجه أحدهم إذا بُشِّر بها؛ ومع ذلك ينسبونها إلى الله؛ فتأمّل قبحَ من ينسب إلى الله ما يسوءه هو ويكرهه؛ فأيُّ سفهٍ أعظمُ من هذا؟ فنزّه الله عمّا لا يرضاه المشركون لأنفسهم؛ ولا تنسب إلى الله ما تكرهه أنت؛ فالله منزّهٌ عن الولدِ والنقصِ كلِّه؛ فاعرف عظمةَ الله وكماله؛ ونزّهه عن كلِّ نقصٍ وعيب؛ فمن عرف الله عظّمه ونزّهه؛ فلا تكن كهؤلاء المتناقضين الذين ينسبون لله ما يكرهون؛ بل نزّه الله عن كلِّ ما لا يليق به؛ فعظّمه، ونزّهه، ووحّده."}},{"n":18,"reflection":{"text":"«أومن ينشأ في الحلية وهو في الخصام غير مبين» — أينسبون إلى الله من يُربّى في الزينةِ (الأنثى) وهو في الجدالِ عاجزٌ عن البيان؟ ففي هذا بيانُ سفهِ نسبتهم الناقصَ إلى الله؛ فتأمّل سخفَ من ينسب إلى الله ما يعدّه ناقصًا، فنزّه الله عن كلِّ نقص، ولا تحكم على الله بأحكامك الجاهلة، بل نزّهه عن كلِّ ما لا يليق به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن كلِّ نقص، وتركُ الحكمِ عليه بالجهل."},"action":{"text":"تأمّل تمامَ فضحِ تناقضهم: أينسبون إلى الله من يُنشَّأ ويُربّى في الحليةِ والزينة — أي الأنثى التي شأنها التزيّن — وهو في الخصامِ والجدالِ غيرُ مبينٍ ولا قادرٍ على إظهارِ حجّته لضعفها؟ فينسبون إلى الله من يعدّونه ناقصًا في زعمهم «أومن ينشأ في الحلية وهو في الخصام غير مبين»؛ ففي هذا بيانُ سفهِ المشركين في نسبتهم إلى الله ما يعدّونه ناقصًا؛ فهم يستنقصون الأنثى، ويعدّونها ضعيفةً في الحجّةِ والبيان، ثم ينسبونها إلى الله؛ فتأمّل سخفَ من ينسب إلى الله ما يعدّه هو ناقصًا وضعيفًا؛ فنزّه الله عن كلِّ نقصٍ وضعف؛ فهو الكاملُ في ذاته وصفاته؛ ولا تحكم على الله بأحكامك الجاهلةِ والباطلة؛ فالله منزّهٌ عن الولدِ والنقصِ كلِّه؛ فاعرف الله بكماله المطلق؛ ونزّهه عن كلِّ ما لا يليق به من النقصِ والعيب؛ فمن عرف كمالَ الله نزّهه عن كلِّ نقص؛ فلا تنسب إلى الله ما لا يليق بجلاله؛ بل أثبت له الكمالَ المطلق، ونزّهه عن كلِّ نقص؛ فعظّم ربك، ونزّهه، ووحّده."}},{"n":19,"reflection":{"text":"«وجعلوا الملائكة الذين هم عباد الرحمن إناثا أشهدوا خلقهم ستكتب شهادتهم ويسألون» — وجعلوا الملائكةَ الذين هم عبادُ الرحمنِ إناثًا، أحضروا خلقهم فعلموا أنهم إناث؟ ستُكتَب شهادتهم الباطلةُ ويُسألون عنها؛ ففي هذا ذمُّ القولِ على الغيبِ بلا علم؛ فاحذر القولَ على الله وفي الغيبِ بلا علم، فإنه مكتوبٌ مسؤولٌ عنه، فلا تقل إلا ما علمت، فالقولُ بلا علمٍ يُكتَب ويُحاسَب عليه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من القولِ على الغيبِ بلا علم، فإنه مكتوبٌ مسؤولٌ عنه."},"action":{"text":"تأمّل ذمَّ الله لقولهم على الغيبِ بلا علم: وجعلوا الملائكةَ الذين هم عبادُ الرحمنِ المكرَّمون إناثًا؛ أشهدوا وحضروا خلقهم فعلموا أنهم إناث؟ لم يشهدوا خلقهم؛ ستُكتَب شهادتهم الباطلةُ عليهم، ويُسألون عنها ويُحاسَبون يومَ القيامة «وجعلوا الملائكة الذين هم عباد الرحمن إناثا أشهدوا خلقهم ستكتب شهادتهم ويسألون»؛ ففي هذا ذمُّ القولِ على الغيبِ بلا علم، وأنه مكتوبٌ مسؤولٌ عنه؛ فوصفوا الملائكةَ بالأنوثةِ بلا علمٍ ولا مشاهدة؛ فاحذر القولَ على الله وفي الغيبِ بلا علم؛ فالقولُ على الله بلا علمٍ من أعظمِ المحرّمات؛ ولا تقف ما ليس لك به علم؛ فلا تقل في الغيبِ ولا في الدينِ إلا ما علمت بدليل؛ واعلم أنّ كلَّ قولٍ تقوله مكتوبٌ عليك، مسؤولٌ عنه؛ ما يلفظ من قولٍ إلا لديه رقيبٌ عتيد؛ فستُكتَب أقوالك وتُسأل عنها؛ فراقب لسانك، ولا تقل إلا حقًّا وعلمًا؛ فلا تخض فيما لا علمَ لك به؛ فمن قال في الغيبِ أو الدينِ بلا علمٍ فقد افترى؛ فالزم العلمَ والدليل؛ واحذر القولَ بلا علم؛ فإنه مكتوبٌ مسؤولٌ عنه يومَ القيامة."}},{"n":20,"reflection":{"text":"«وقالوا لو شاء الرحمن ما عبدناهم ما لهم بذلك من علم إن هم إلا يخرصون» — وقالوا: لو شاء الرحمنُ ما عبدنا الملائكة، ما لهم بذلك من علمٍ، ما هم إلا يكذبون ويظنّون؛ ففي هذا ردُّ احتجاجهم بالقدرِ على الشرك؛ فاحذر الاحتجاجَ بالقدرِ على المعاصي، فإنه حجّةٌ باطلةٌ بلا علم، فأنت مأمورٌ منهيٌّ مخيَّر، فلا تعلّق شركك أو معصيتك على مشيئةِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ الاحتجاجِ بالقدرِ على الشركِ والمعصية."},"action":{"text":"تأمّل ردَّ الله على احتجاجهم بالقدر: وقالوا: لو شاء الرحمنُ ما عبدنا الملائكةَ والأصنام؛ فاحتجّوا بمشيئةِ الله على شركهم؛ فردّ الله عليهم: ما لهم بذلك من علمٍ يصحّح احتجاجهم؛ إن هم إلا يخرصون ويكذبون ويظنّون الظنون «وقالوا لو شاء الرحمن ما عبدناهم ما لهم بذلك من علم إن هم إلا يخرصون»؛ ففي هذا ردُّ احتجاجِ المشركين بالقدرِ على شركهم؛ فاحتجّوا بأنّ الله لو شاء لمنعهم؛ وهذه حجّةٌ باطلةٌ داحضة؛ فإنّ الله وإن كان بمشيئتِه يقع كلُّ شيء، فقد أمر العبادَ ونهاهم وأقام عليهم الحجّةَ بالرسل، وأعطاهم العقلَ والاختيار؛ فاحتجاجهم بالقدرِ على الشركِ باطلٌ؛ فاحذر الاحتجاجَ بالقدرِ على المعاصي والشرك؛ فإنه حجّةٌ باطلةٌ لا علمَ لأصحابها بها؛ فلو صحّ الاحتجاجُ بالقدرِ لما عُذّب أحد؛ سيقول الذين أشركوا لو شاء الله ما أشركنا... قل هل عندكم من علمٍ فتخرجوه لنا إن تتّبعون إلا الظن؛ فأنت مأمورٌ منهيٌّ مخيَّرٌ مكلَّف؛ فلا تعلّق شركك أو معصيتك على مشيئةِ الله؛ بل آمن بالقدر، ولا تحتجّ به على المعاصي؛ فالقدرُ يُؤمَن به ولا يُحتَجّ به على الذنوب؛ فاعمل، ولا تتّكل على القدر."}}]},{"title":"التقليدُ الأعمى للآباءِ وردُّه، وعاقبةُ المكذّبين المعاندين","range":[21,25],"theme":"نفيُ أيِّ مستندٍ للمشركين من كتابٍ في شركهم، وأنّ مستندهم تقليدُ الآباءِ الأعمى، وأنّ هذه حجّةُ المترفين المكذّبين في كلِّ قريةٍ أُرسِل إليها نذير، وأنهم يردّون الحقَّ الأهدى تعصّبًا للتقليد، فكانت عاقبةُ المكذّبين الانتقامَ والهلاك","verses":[{"n":21,"reflection":{"text":"«أم آتيناهم كتابا من قبله فهم به مستمسكون» — أآتيناهم كتابًا من قبلِ القرآنِ يأمرهم بالشركِ فهم به متمسّكون؟ ففي هذا نفيُ أيِّ مستندٍ للمشركين في شركهم؛ فاعلم أنّ الشركَ لا مستندَ له من كتابٍ ولا وحي، فلا تتّبع في دينك إلا ما جاء به الوحي، فمن لا دليلَ عنده من الوحي فدعواه باطلة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ ما جاء به الوحي، وإدراكُ أنّ الشركَ لا مستندَ له."},"action":{"text":"تأمّل نفيَ الله لأيِّ مستندٍ للمشركين: أم آتينا هؤلاء المشركين كتابًا من قبلِ القرآنِ يأمرهم بالشركِ ويأذن لهم به، فهم به مستمسكون ومحتجّون؟ لم يؤتهم الله كتابًا كذلك «أم آتيناهم كتابا من قبله فهم به مستمسكون»؛ ففي هذا نفيُ أيِّ مستندٍ للمشركين في شركهم من كتابٍ أو وحي؛ فليس عندهم كتابٌ من الله يأمرهم بالشرك؛ فشركهم لا مستندَ له إلا الظنَّ والهوى والتقليد؛ فاعلم أنّ الشركَ لا مستندَ له من كتابٍ ولا وحيٍ ولا برهان؛ فما أنزل الله بالشركِ من سلطان؛ فكلُّ ما جاءت به الرسلُ والكتبُ هو التوحيد؛ فلا تتّبع في دينك إلا ما جاء به الوحيُ الصحيح؛ فمن لا دليلَ عنده من الوحيِ على قوله ومعتقده فدعواه باطلةٌ مردودة؛ قل هاتوا برهانكم إن كنتم صادقين؛ فاجعل بناءَ عقيدتك ودينك على الوحي، لا على الظنِّ والهوى والتقليد؛ فمن بنى دينه على الوحيِ ثبت واهتدى، ومن بناه على الظنِّ والهوى ضلّ؛ فالزم ما جاء به الوحي؛ واحذر الشركَ الذي لا مستندَ له."}},{"n":22,"reflection":{"text":"«بل قالوا إنا وجدنا آباءنا على أمة وإنا على آثارهم مهتدون» — بل قالوا: إنا وجدنا آباءنا على دينٍ وطريقة، وإنا على آثارهم مهتدون؛ ففي هذا بيانُ أنّ مستندهم التقليدُ الأعمى للآباء؛ فاحذر التقليدَ الأعمى في الدينِ بلا دليل، فليس اتّباعُ الآباءِ حجّةً على الحقّ، بل زِن ما عليه آباؤك بميزانِ الوحي، فالتقليدُ الأعمى سببُ الضلال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التقليدِ الأعمى للآباء، ووزنُ ما عليهم بميزانِ الوحي."},"action":{"text":"تأمّل بيانَ مستندِ المشركين الحقيقي: بل قالوا معتذرين عن شركهم: إنا وجدنا آباءنا على أمّةٍ ودينٍ وطريقة، وإنا على آثارهم وطريقتهم مهتدون، نقتدي بهم «بل قالوا إنا وجدنا آباءنا على أمة وإنا على آثارهم مهتدون»؛ ففي هذا بيانُ أنّ مستندهم في الشركِ ليس دليلًا ولا برهانًا، بل التقليدُ الأعمى للآباء؛ فاعتمدوا على تقليدِ آبائهم لا على الحجّةِ والدليل؛ فاحذر التقليدَ الأعمى في الدينِ والعقيدةِ بلا دليلٍ ولا برهان؛ فليس اتّباعُ الآباءِ والأجدادِ حجّةً على الحقّ؛ أولو كان آباؤهم لا يعقلون شيئًا ولا يهتدون؛ فزِن ما وجدت عليه آباءك ومجتمعك بميزانِ الوحيِ والدليل؛ فما وافق الحقَّ قبلته ولو خالف آباءك، وما خالفه رددته ولو كان عليه آباؤك؛ فلا تجعل تقليدَ الآباءِ ميزانًا للحقِّ والباطل؛ بل اجعل الميزانَ الوحيَ والدليل؛ فالتقليدُ الأعمى للآباءِ من غيرِ نظرٍ في الدليلِ سببُ الضلالِ والهلاك؛ فكم من ضالٍّ ضلّ بتقليدِ آبائه؛ فاتّبع الحقَّ بدليله، ولا تقلّد الآباءَ على الباطل؛ فالحقُّ أحقُّ أن يُتّبَع من تقليدِ الآباء."}},{"n":23,"reflection":{"text":"«وكذلك ما أرسلنا من قبلك في قرية من نذير إلا قال مترفوها إنا وجدنا آباءنا على أمة وإنا على آثارهم مقتدون» — وكذلك ما أرسلنا في قريةٍ من نذيرٍ قبلك إلا قال مترفوها: إنا وجدنا آباءنا على دينٍ وإنا على آثارهم مقتدون؛ ففي هذا أنّ التقليدَ الأعمى حجّةُ المكذّبين في كلِّ زمان؛ فاحذر أن تكون من المقلّدين المكذّبين، فحجّةُ التقليدِ حجّةُ كلِّ مكذّب، فاتّبع الحقَّ بدليله لا بتقليدِ الآباء، فالمترفون أكثرُ الناسِ تعلّقًا بالتقليد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التقليدِ الأعمى، فهو حجّةُ المكذّبين في كلِّ زمان."},"action":{"text":"تأمّل أنّ التقليدَ حجّةُ المكذّبين في كلِّ زمان: وكذلك — كحالِ مشركي قومك — ما أرسلنا من قبلك في قريةٍ من نذيرٍ يحذّرهم، إلا قال مترفوها — المنعَّمون المتكبّرون منهم: إنا وجدنا آباءنا على أمّةٍ ودينٍ وطريقة، وإنا على آثارهم مقتدون مقلّدون «وكذلك ما أرسلنا من قبلك في قرية من نذير إلا قال مترفوها إنا وجدنا آباءنا على أمة وإنا على آثارهم مقتدون»؛ ففي هذا بيانُ أنّ التقليدَ الأعمى للآباءِ حجّةُ المكذّبين في كلِّ زمانٍ ومكان؛ فما من نذيرٍ إلا واجهه المترفون بهذه الحجّةِ الباطلة: تقليدِ الآباء؛ فاحذر أن تكون من المقلّدين المكذّبين الذين يردّون الحقَّ بحجّةِ تقليدِ الآباء؛ فحجّةُ التقليدِ حجّةُ كلِّ مكذّبٍ معاند؛ ولاحظ أنّ المترفين — المنعَّمين المتكبّرين — هم أكثرُ الناسِ تعلّقًا بالتقليدِ وردًّا للحق؛ لأنّ الحقَّ يهدّد ترفهم وكبرهم؛ فاتّبع الحقَّ بدليله وبرهانه، لا بتقليدِ الآباءِ والأجداد؛ فلا تجعل ما عليه آباؤك ومجتمعك حجّةً على الحق؛ بل زِنه بميزانِ الوحي؛ فمن اتّبع الحقَّ بدليله نجا، ومن قلّد الآباءَ على الباطلِ هلك؛ فتحرّر من ربقةِ التقليدِ الأعمى، واتّبع الحقَّ حيث كان."}},{"n":24,"reflection":{"text":"«قال أولو جئتكم بأهدى مما وجدتم عليه آباءكم قالوا إنا بما أرسلتم به كافرون» — قال النذير: أتتّبعون آباءكم ولو جئتكم بأهدى مما وجدتم عليه آباءكم؟ قالوا: إنا بما أُرسِلتم به كافرون؛ ففي هذا عنادُ المقلّدين ورفضهم الحقَّ ولو كان أهدى؛ فاحذر أن ترفض الحقَّ الأهدى تمسّكًا بالتقليد، بل اقبل الأهدى والأصوب، فمن رفض الحقَّ الأهدى تعصّبًا للتقليد فهو معاند.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ الحقِّ الأهدى، وتركُ التعصّبِ للتقليد."},"action":{"text":"تأمّل عنادَ المقلّدين: قال النذيرُ لهم محتجًّا: أتتّبعون آباءكم ولو جئتكم بدينٍ أهدى وأصوبَ مما وجدتم عليه آباءكم؟ أفلا تتركون تقليدهم لما هو أهدى؟ فأجابوا بعنادٍ وإصرار: إنا بما أُرسِلتم به من الحقِّ كافرون جاحدون «قال أولو جئتكم بأهدى مما وجدتم عليه آباءكم قالوا إنا بما أرسلتم به كافرون»؛ ففي هذا بيانُ عنادِ المقلّدين ورفضهم الحقَّ ولو كان أهدى وأصوبَ من طريقةِ آبائهم؛ فتمسّكوا بالتقليدِ الأعمى حتى ردّوا الحقَّ الأهدى؛ فاحذر أن ترفض الحقَّ الأهدى والأصوبَ تمسّكًا بالتقليدِ والعادةِ والموروث؛ فالعاقلُ يتّبع الأهدى والأصوبَ ولو خالف ما عليه آباؤه؛ فإذا تبيّن لك أنّ الحقَّ أهدى مما أنت عليه فاتّبعه؛ ولا تردّه تعصّبًا للتقليدِ والعادة؛ فمن رفض الحقَّ الأهدى تعصّبًا للتقليدِ فهو معاندٌ مكابر؛ الذين يستمعون القولَ فيتّبعون أحسنه أولئك الذين هداهم الله؛ فاتّبع أحسنَ القولِ وأهداه؛ واقبل الحقَّ الأصوبَ ولو خالف موروثك؛ فمن قبل الأهدى اهتدى، ومن رفضه تعصّبًا ضلّ؛ فكن مع الحقِّ الأهدى، لا مع التقليدِ الأعمى."}},{"n":25,"reflection":{"text":"«فانتقمنا منهم فانظر كيف كان عاقبة المكذبين» — فانتقمنا من المكذّبين المعاندين، فانظر كيف كانت عاقبتهم من الهلاك؛ ففي هذا وعيدُ المكذّبين وعبرةُ عاقبتهم؛ فاعتبر بعاقبةِ المكذّبين المعاندين، واحذر أن تسلك سبيلهم، فمن كذّب الحقَّ وعاند أهلكه الله، فاتّبع الحقَّ لتنجو من عاقبتهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعاقبةِ المكذّبين المعاندين، واتّباعُ الحقِّ للنجاة."},"action":{"text":"تأمّل عاقبةَ المكذّبين المعاندين: فانتقمنا من المكذّبين المعاندين الذين ردّوا الحقَّ تعصّبًا للتقليد، فأهلكناهم؛ فانظر يا محمدُ ويا أيها الإنسان، كيف كانت عاقبةُ المكذّبين من الهلاكِ والدمار «فانتقمنا منهم فانظر كيف كان عاقبة المكذبين»؛ ففي هذا وعيدُ المكذّبين المعاندين، والدعوةُ للاعتبارِ بعاقبتهم؛ فمن كذّب الحقَّ وعاند وأصرّ انتقم الله منه وأهلكه؛ فاعتبر بعاقبةِ المكذّبين المعاندين للحق؛ واحذر أن تسلك سبيلهم في التكذيبِ والعنادِ والتقليدِ الأعمى؛ فمن كذّب الحقَّ وعاند أهلكه الله كما أهلكهم؛ فسِر في الأرضِ وانظر كيف كان عاقبةُ المكذّبين؛ فاجعل من مصارعهم عبرةً تحملك على الإيمانِ واتّباعِ الحق؛ واتّبع الحقَّ الذي جاءت به الرسلُ لتنجو من عاقبتهم؛ فمن اتّبع الحقَّ نجا، ومن كذّبه وعاند هلك؛ فاختر لنفسك سبيلَ الناجين المتّبعين للحق، لا سبيلَ المكذّبين المعاندين الهالكين؛ فالعاقبةُ للمتّقين، والهلاكُ للمكذّبين."}}]},{"title":"براءةُ إبراهيمَ من الشرك وكلمةُ التوحيدِ الباقية، وعنادُ المكذّبين","range":[26,30],"theme":"إعلانُ إبراهيمَ البراءةَ مما يعبد قومه إلا الذي فطره، وجعلُ الله كلمةَ التوحيدِ باقيةً في ذريّته، وأنّ الله متّع المشركين وآباءهم حتى جاءهم الحقُّ ورسولٌ مبين، ولمّا جاءهم الحقُّ قالوا هذا سحرٌ وإنا به كافرون","verses":[{"n":26,"reflection":{"text":"«وإذ قال إبراهيم لأبيه وقومه إنني براء مما تعبدون» — واذكر إذ قال إبراهيمُ لأبيه وقومه: إنني بريءٌ مما تعبدون من دونِ الله؛ ففي هذا البراءةُ من الشركِ وأهله؛ فتبرّأ من الشركِ وكلِّ معبودٍ سوى الله، فالبراءةُ من الشركِ ركنُ التوحيد، فأعلن براءتك من عبادةِ غيرِ الله كما أعلن إبراهيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"البراءةُ من الشركِ وكلِّ معبودٍ سوى الله، فهي ركنُ التوحيد."},"action":{"text":"تأمّل براءةَ إبراهيمَ من الشرك: واذكر إذ قال إبراهيمُ خليلُ الرحمنِ لأبيه وقومه معلنًا براءته: إنني براءٌ وبريءٌ مما تعبدون من دونِ الله من الأصنامِ والأنداد «وإذ قال إبراهيم لأبيه وقومه إنني براء مما تعبدون»؛ ففي هذا إعلانُ البراءةِ من الشركِ وأهله ومعبوداتهم؛ فالتوحيدُ لا يتمّ إلا بالبراءةِ من الشركِ وأهله؛ فتبرّأ من الشركِ وكلِّ معبودٍ سوى الله؛ فالبراءةُ من الشركِ وأهله ركنٌ من أركانِ التوحيد؛ قد كانت لكم أسوةٌ حسنةٌ في إبراهيمَ والذين معه إذ قالوا لقومهم إنا برآءُ منكم ومما تعبدون من دونِ الله كفرنا بكم؛ فأعلن براءتك من عبادةِ غيرِ الله، ومن الشركِ وأهله، كما أعلن إبراهيم؛ فمن يكفر بالطاغوتِ ويؤمن بالله فقد استمسك بالعروةِ الوثقى؛ فحقّق التوحيدَ بأمرين: البراءةِ من الشرك، والإخلاصِ لله؛ فاتبرّأ من كلِّ ما يُعبَد من دونِ الله؛ وأخلص العبادةَ لله وحده؛ فبالبراءةِ من الشركِ والإخلاصِ لله يكمل توحيدك."}},{"n":27,"reflection":{"text":"«إلا الذي فطرني فإنه سيهدين» — إلا الذي خلقني، فإنه سيهديني إلى الحقّ؛ ففي هذا استثناءُ الخالقِ من البراءةِ وتوحيدُه؛ فوحّد الخالقَ الذي فطرك، وثق بهدايته، فمن فطرك يهديك، فاعبد خالقك وحده وارجُ هدايته، فالبراءةُ من كلِّ معبودٍ إلا الخالق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الخالقِ الذي فطرك، والثقةُ بهدايته."},"action":{"text":"تأمّل تمامَ كلمةِ إبراهيم: إنني براءٌ مما تعبدون إلا الذي فطرني وخلقني، فإنه سيهديني إلى الحقِّ والصراطِ المستقيم «إلا الذي فطرني فإنه سيهدين»؛ ففي هذا استثناءُ الخالقِ من البراءة، وتوحيدُه بالعبادة، والثقةُ بهدايته؛ فتبرّأ إبراهيمُ من كلِّ معبودٍ إلا الخالقَ الذي فطره؛ فوحّد الخالقَ الذي فطرك وخلقك؛ فهو وحده المستحقُّ للعبادة؛ وثق بهداية الله لك؛ فمن فطرك وخلقك هو الذي يهديك ويوفّقك؛ فاعبد خالقك وحده، وارجُ هدايته وتوفيقه؛ فالبراءةُ من كلِّ معبودٍ إلا الخالق؛ فأخلص العبادةَ للخالقِ الفاطر؛ ولا تعبد ما لا يخلق ولا يهدي؛ فمن وحّد خالقه ووثق بهدايته اهتدى؛ فاطلب الهدايةَ من الله الذي فطرك؛ فهو الذي يهديك إلى الحق؛ فاجعل عبادتك ورجاءك وثقتك بالخالقِ الذي فطرك؛ فبتوحيده والثقةِ بهدايته تُنال السعادة."}},{"n":28,"reflection":{"text":"«وجعلها كلمة باقية في عقبه لعلهم يرجعون» — وجعل الله كلمةَ التوحيدِ باقيةً في ذريةِ إبراهيمَ لعلّهم يرجعون إليها؛ ففي هذا بقاءُ كلمةِ التوحيدِ في ذريّةِ إبراهيم؛ فاحرص على توريثِ التوحيدِ لذريّتك، فكلمةُ التوحيدِ ميراثٌ باقٍ، فاجعل التوحيدَ كلمةً باقيةً في أهلك وذريّتك بالتربيةِ عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توريثُ التوحيدِ للذريّة، وجعلُه كلمةً باقيةً فيهم."},"action":{"text":"تأمّل بقاءَ كلمةِ التوحيد: وجعل الله كلمةَ التوحيدِ — لا إله إلا الله، أو البراءةَ من الشركِ والإخلاصَ لله — كلمةً باقيةً في عقبِ إبراهيمَ وذريّته، يتوارثونها جيلًا بعد جيل، لعلّهم يرجعون إليها إذا انحرفوا «وجعلها كلمة باقية في عقبه لعلهم يرجعون»؛ ففي هذا بيانُ بقاءِ كلمةِ التوحيدِ في ذريّةِ إبراهيم؛ فما زال في ذريّته من يوحّد الله ويدعو إليه؛ فاحرص على توريثِ التوحيدِ والدينِ لذريّتك من بعدك؛ فكلمةُ التوحيدِ أعظمُ ميراثٍ تتركه لذريّتك؛ فاجعل التوحيدَ كلمةً باقيةً في أهلك وذريّتك؛ ورّثهم العقيدةَ الصحيحةَ والتوحيدَ الخالص؛ وربِّهم على التوحيدِ والدين؛ فإذا انحرف بعضهم رجع إلى ما ورثه من التوحيد؛ فاعتنِ بتربيةِ ذريّتك على التوحيدِ والدين؛ كما وصّى إبراهيمُ بنيه ويعقوبُ يا بنيّ إنّ الله اصطفى لكم الدينَ فلا تموتنّ إلا وأنتم مسلمون؛ فمن ورّث ذريّته التوحيدَ فقد ترك لهم أعظمَ ميراث؛ فاجعل همّك توريثَ التوحيدِ والدينِ لأهلك وذريّتك."}},{"n":29,"reflection":{"text":"«بل متعت هؤلاء وآباءهم حتى جاءهم الحق ورسول مبين» — بل متّعتُ هؤلاء المشركين وآباءهم بالدنيا حتى جاءهم الحقُّ (القرآن) ورسولٌ مبين؛ ففي هذا بيانُ أنّ الإمهالَ لا يعني الرضا؛ فلا يغرّنك إمهالُ الله للكافرين بالتمتّع، فالإمهالُ ابتلاءٌ لا إكرام، فاغتنم نعمَ الله في طاعته، ولا تغترّ بالتمتّعِ في المعصية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترارِ بالإمهالِ والتمتّع، واغتنامُ النعمِ في الطاعة."},"action":{"text":"تأمّل بيانَ الله لحكمةِ الإمهال: بل متّعتُ هؤلاء المشركين وآباءهم بالدنيا ونعيمها، ولم أعاجلهم بالعقوبة، حتى جاءهم الحقُّ — القرآنُ — ورسولٌ مبينٌ يوضّح لهم الحق «بل متعت هؤلاء وآباءهم حتى جاءهم الحق ورسول مبين»؛ ففي هذا بيانُ أنّ إمهالَ الله للكافرين وتمتيعهم بالدنيا ليس رضًا عنهم، بل استدراجٌ وإقامةٌ للحجّة؛ فأمهلهم ومتّعهم حتى جاءهم الحقُّ والرسول؛ فلا يغرّنك إمهالُ الله للكافرين وتمتيعهم بالدنيا؛ ولا تظنّ أنّ ذلك إكرامٌ أو رضًا؛ فالإمهالُ والتمتيعُ ابتلاءٌ واستدراج، لا إكرامٌ ولا رضا؛ ولا يحسبنّ الذين كفروا أنما نملي لهم خيرٌ لأنفسهم إنما نملي لهم ليزدادوا إثمًا؛ فاغتنم نعمَ الله وتمتّعك بالدنيا في طاعته وشكره؛ ولا تغترّ بالتمتّعِ في المعصيةِ والإعراض؛ فكم من ممتَّعٍ في الدنيا مستدرَجٍ إلى الهلاك؛ فاجعل نعمَ الله عونًا على طاعته، لا سببًا للغفلةِ والإعراض؛ فمن اغترّ بالتمتّعِ في المعصيةِ خسر، ومن اغتنم النعمَ في الطاعةِ ربح."}},{"n":30,"reflection":{"text":"«ولما جاءهم الحق قالوا هذا سحر وإنا به كافرون» — ولمّا جاءهم الحقُّ (القرآن) قالوا: هذا سحرٌ وإنا به كافرون؛ ففي هذا عنادُ المشركين ورميهم الحقَّ بالسحر؛ فاحذر ردَّ الحقِّ بالتهمِ الباطلة، فرميُ الحقِّ بالسحرِ من عنادِ المكذّبين، فاقبل الحقَّ بإنصاف، ولا تردّه بالتهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ الحقِّ بإنصاف، وتركُ ردِّه بالتهمِ الباطلة."},"action":{"text":"تأمّل عنادَ المشركين عند مجيءِ الحق: ولمّا جاءهم الحقُّ — القرآنُ الواضحُ المعجز — قالوا رادّين له بلا حجّة: هذا سحرٌ، وإنا به كافرون جاحدون «ولما جاءهم الحق قالوا هذا سحر وإنا به كافرون»؛ ففي هذا بيانُ عنادِ المشركين ورميهم الحقَّ بالسحرِ والكفرِ به؛ فلمّا عجزوا عن معارضته رموه بالسحر؛ فاحذر ردَّ الحقِّ بالتهمِ الباطلةِ والأوصافِ الكاذبة؛ فرميُ الحقِّ بالسحرِ أو الكذبِ أو الجنونِ من عنادِ المكذّبين وطريقتهم؛ كذلك ما أتى الذين من قبلهم من رسولٍ إلا قالوا ساحرٌ أو مجنون؛ فاقبل الحقَّ بإنصافٍ وتجرّد؛ ولا تردّه بالتهمِ والأوصافِ الباطلة؛ فمن ردّ الحقَّ بالتهمةِ فقد أعرض عن الإنصاف؛ فاجعل ميزانك في قبولِ الحقِّ الحجّةَ والدليل، لا التهمَ والدعاوى؛ فمن قبل الحقَّ ببرهانه اهتدى، ومن ردّه بالتهمِ الباطلةِ عاند وضلّ؛ فلا تكن من المعاندين الذين يردّون الحقَّ بالتهم؛ بل كن من المنصفين الذين يقبلونه ببرهانه."}}]},{"title":"اعتراضهم على نزولِ القرآن، وقسمةُ الرزق، وهوانُ زخرفِ الدنيا","range":[31,35],"theme":"اعتراضُ المشركين على نزولِ القرآنِ على غيرِ عظيمِ القريتين، وأنّ الله هو الذي يقسم المعيشةَ ويرفع بعضهم فوق بعضٍ درجاتٍ ورحمتُه خيرٌ مما يجمعون، وأنّ الدنيا هيّنةٌ على الله لولا فتنةُ الناسِ لأعطى الكافرين سقوفًا من فضّةٍ وأبوابًا وسررًا وزخرفًا وأنّ كلَّ ذلك متاعُ الدنيا والآخرةُ للمتّقين","verses":[{"n":31,"reflection":{"text":"«وقالوا لولا نزل هذا القرآن على رجل من القريتين عظيم» — وقالوا: هلّا نُزّل القرآنُ على رجلٍ عظيمٍ من مكّةَ أو الطائف (بالجاهِ والمال)؟ ففي هذا اعتراضهم على اختيارِ الله للرسول بمقاييسِ الدنيا؛ فاحذر أن تزن الفضلَ بمقاييسِ الدنيا (الجاهِ والمال)، فالفضلُ بيدِ الله يؤتيه من يشاء، فلا تعترض على قسمةِ الله، والعبرةُ بالتقوى لا بالمال.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ وزنِ الفضلِ بمقاييسِ الدنيا، والتسليمُ لقسمةِ الله."},"action":{"text":"تأمّل اعتراضَ المشركين على اختيارِ الرسول: وقالوا معترضين: هلّا نُزّل هذا القرآنُ على رجلٍ عظيمِ الجاهِ والمالِ من إحدى القريتين — مكّةَ أو الطائف — بدلًا من محمدٍ اليتيمِ الفقير؟ فوزنوا استحقاقَ النبوّةِ بمقاييسِ الدنيا من الجاهِ والمال «وقالوا لولا نزل هذا القرآن على رجل من القريتين عظيم»؛ ففي هذا اعتراضُ المشركين على اختيارِ الله لرسوله بمقاييسِ الدنيا؛ فظنّوا أنّ النبوّةَ تُنال بالجاهِ والمال، لا بالاصطفاءِ والتقوى؛ فاحذر أن تزن الفضلَ والقدرَ بمقاييسِ الدنيا من الجاهِ والمالِ والمنصب؛ فالفضلُ الحقيقيُّ بيدِ الله يؤتيه من يشاء بحكمته؛ الله أعلمُ حيث يجعل رسالته؛ فليست العبرةُ بالجاهِ والمال، بل بالتقوى والاصطفاء؛ إنّ أكرمكم عند الله أتقاكم؛ فلا تعترض على قسمةِ الله وفضلِه واختياره؛ ولا تحتقر أحدًا لفقره، ولا تعظّم أحدًا لماله؛ فالعبرةُ بالتقوى والإيمان، لا بالدنيا وزخرفها؛ فكم من فقيرٍ خيرٌ عند الله من غنيّ؛ فوزن الأمورَ بميزانِ التقوى، لا بميزانِ الدنيا؛ فمن وزن بمقاييسِ الدنيا ضلّ، ومن وزن بميزانِ التقوى اهتدى."}},{"n":32,"reflection":{"text":"«أهم يقسمون رحمت ربك نحن قسمنا بينهم معيشتهم في الحياة الدنيا ورفعنا بعضهم فوق بعض درجات ليتخذ بعضهم بعضا سخريا ورحمت ربك خير مما يجمعون» — أهم يقسمون رحمةَ ربّك (النبوّة)؟ نحن قسمنا بينهم معيشتهم ورفعنا بعضهم فوق بعضٍ درجاتٍ ليسخّر بعضهم بعضًا، ورحمةُ ربّك خيرٌ مما يجمعون؛ ففي هذا أنّ القسمةَ بيدِ الله والتفاوتَ بحكمته؛ فاعلم أنّ الله قسم الأرزاقَ والمنازلَ بحكمته، فارضَ بقسمته، ولا تعترض على تفاوتِ الناس، ورحمةُ الله خيرٌ من كلِّ ما يُجمَع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرضا بقسمةِ الله وتفاوتِ الناس، وطلبُ رحمتِه خيرًا مما يُجمَع."},"action":{"text":"تأمّل ردَّ الله على اعتراضهم: أهم يقسمون رحمةَ ربّك فيضعون النبوّةَ حيث شاؤوا؟ ليس ذلك إليهم؛ نحن قسمنا بينهم معيشتهم وأرزاقهم في الحياةِ الدنيا بحكمتنا؛ ورفعنا بعضهم فوق بعضٍ درجاتٍ في الرزقِ والجاهِ والقوّة، ليتّخذ بعضهم بعضًا سخريًّا يخدم بعضهم بعضًا فتنتظم الحياة؛ ورحمةُ ربّك — الجنّةُ والإيمانُ والنبوّة — خيرٌ مما يجمعون من حطامِ الدنيا «أهم يقسمون رحمت ربك نحن قسمنا بينهم معيشتهم في الحياة الدنيا ورفعنا بعضهم فوق بعض درجات ليتخذ بعضهم بعضا سخريا ورحمت ربك خير مما يجمعون»؛ ففي هذا بيانُ أنّ القسمةَ بيدِ الله، وأنّ التفاوتَ بين الناسِ بحكمته؛ فإذا كانوا لا يملكون قسمةَ أرزاقِ الدنيا، فكيف يقسمون النبوّة؟ فاعلم أنّ الله قسم الأرزاقَ والمنازلَ بين الناسِ بحكمته وعلمه؛ ورفع بعضهم فوق بعضٍ درجاتٍ لحكمةِ انتظامِ الحياةِ وتسخيرِ بعضهم لبعض؛ فارضَ بقسمةِ الله لك من الرزقِ والمنزلة؛ ولا تعترض على تفاوتِ الناسِ في الأرزاقِ والمنازل؛ فهو بحكمةٍ من الله؛ ولا تتمنَّ ما فضّل الله به بعضكم على بعض؛ واعلم أنّ رحمةَ الله — الإيمانَ والجنّةَ — خيرٌ من كلِّ ما يجمعه الناسُ من الدنيا؛ فاطلب رحمةَ الله، فهي خيرٌ مما يجمعون؛ فاجعل همّك رحمةَ الله لا حطامَ الدنيا؛ فمن رضي بقسمةِ الله وطلب رحمته فاز."}},{"n":33,"reflection":{"text":"«ولولا أن يكون الناس أمة واحدة لجعلنا لمن يكفر بالرحمن لبيوتهم سقفا من فضة ومعارج عليها يظهرون» — ولولا أن يجتمع الناسُ على الكفرِ لهوانِ الدنيا لجعلنا لبيوتِ الكافرين سقوفًا من فضّةٍ ومصاعدَ يصعدون عليها؛ ففي هذا بيانُ هوانِ الدنيا على الله؛ فاعلم أنّ الدنيا هيّنةٌ على الله يعطيها الكافر، فلا تغترّ بها ولا تجعلها غايتك، فالدنيا لا وزنَ لها عند الله يعطيها من يحبّ ومن لا يحبّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ هوانِ الدنيا على الله، وعدمُ الاغترارِ بها."},"action":{"text":"تأمّل بيانَ هوانِ الدنيا على الله: ولولا أن يكون الناسُ أمّةً واحدةً على الكفرِ — لو رأوا الكافرَ يُعطى الدنيا فيميلون كلُّهم إلى الكفرِ طلبًا لها — لجعلنا لمن يكفر بالرحمنِ لبيوتهم سقوفًا من فضّة، ومعارجَ ومصاعدَ من فضّةٍ يصعدون عليها إلى غرفهم «ولولا أن يكون الناس أمة واحدة لجعلنا لمن يكفر بالرحمن لبيوتهم سقفا من فضة ومعارج عليها يظهرون»؛ ففي هذا بيانُ هوانِ الدنيا على الله؛ فلولا خشيةُ فتنةِ الناسِ لأعطى الكفّارَ من زخرفِ الدنيا ما شاء؛ فالدنيا هيّنةٌ حقيرةٌ على الله، يعطيها الكافرَ الذي يبغضه؛ فاعلم أنّ الدنيا لا وزنَ لها عند الله؛ لو كانت الدنيا تعدل عند الله جناحَ بعوضةٍ ما سقى كافرًا منها شربةَ ماء؛ فلا تغترّ بالدنيا وزخرفها؛ ولا تجعلها غايتك ومطلبك الأكبر؛ فالدنيا يعطيها الله من يحبّ ومن لا يحبّ، ولا يعطي الدينَ والإيمانَ إلا من يحبّ؛ فمن أُعطي الدنيا فليس ذلك دليلَ محبّةِ الله له؛ بل قد يكون استدراجًا؛ فاطلب ما يدلّ على محبّةِ الله: الإيمانَ والتقوى والدينَ؛ ولا تجعل همّك الدنيا الهيّنةَ على الله؛ فمن جعل الدنيا أكبرَ همّه هان على الله."}},{"n":34,"reflection":{"text":"«ولبيوتهم أبوابا وسررا عليها يتكئون» — ولجعلنا لبيوتِ الكافرين أبوابًا من فضّةٍ وسررًا يتّكئون عليها؛ ففي هذا تمامُ بيانِ هوانِ الدنيا؛ فاعلم أنّ متاعَ الدنيا كلَّه هيّنٌ على الله، فلا تحرص على زخرفِ الدنيا، بل اطلب نعيمَ الآخرةِ الباقي، فالدنيا زائلةٌ والآخرةُ خيرٌ وأبقى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ الحرصِ على زخرفِ الدنيا، وطلبُ نعيمِ الآخرة."},"action":{"text":"تأمّل تمامَ بيانِ هوانِ الدنيا: ولجعلنا لبيوتِ الكافرين أبوابًا من فضّة، وسررًا وأسرّةً من فضّةٍ يتّكئون عليها متنعّمين «ولبيوتهم أبوابا وسررا عليها يتكئون»؛ ففي هذا تمامُ بيانِ هوانِ الدنيا على الله؛ فلو شاء لأعطى الكفّارَ القصورَ والأبوابَ والأسرّةَ من الفضّة؛ فمتاعُ الدنيا كلُّه هيّنٌ حقيرٌ على الله؛ فاعلم أنّ زخرفَ الدنيا ومتاعها كلَّه هيّنٌ على الله؛ فلا تحرص على زخرفِ الدنيا وزينتها؛ ولا تجعلها أكبرَ همّك؛ فالدنيا زائلةٌ فانية؛ وما الحياةُ الدنيا إلا متاعُ الغرور؛ بل اطلب نعيمَ الآخرةِ الباقي؛ فما عند الله خيرٌ وأبقى؛ والآخرةُ خيرٌ وأبقى؛ فاجعل حرصك على الآخرةِ لا على الدنيا؛ فمن حرص على زخرفِ الدنيا وجعلها غايته خسر الآخرة؛ ومن زهد في زخرفها وطلب الآخرةَ ربح؛ فلا تنظر إلى ما متّع الله به الكافرين من زخرفِ الدنيا؛ ولا تمدّنّ عينيك إلى ما متّعنا به أزواجًا منهم زهرةَ الحياةِ الدنيا؛ فاطلب النعيمَ الباقي، ولا تغترّ بالزخرفِ الفاني."}},{"n":35,"reflection":{"text":"«وزخرفا وإن كل ذلك لما متاع الحياة الدنيا والآخرة عند ربك للمتقين» — وزينةً وذهبًا، وما كلُّ ذلك إلا متاعُ الحياةِ الدنيا، والآخرةُ عند ربّك للمتّقين؛ ففي هذا حصرُ الزخرفِ في متاعِ الدنيا وتخصيصُ الآخرةِ للمتّقين؛ فاطلب الآخرةَ بالتقوى، فهي خيرٌ من زخرفِ الدنيا، فالزخرفُ متاعٌ زائل، والآخرةُ للمتّقين، فاعمل للآخرةِ بالتقوى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الآخرةِ بالتقوى، فهي خيرٌ من زخرفِ الدنيا الزائل."},"action":{"text":"تأمّل حصرَ زخرفِ الدنيا وتخصيصَ الآخرةِ للمتّقين: ولجعلنا لهم زخرفًا — زينةً وذهبًا وأثاثًا؛ وما كلُّ ذلك الزخرفِ والمتاعِ إلا متاعُ الحياةِ الدنيا الزائلُ الحقير؛ والآخرةُ ونعيمها الباقي عند ربّك خالصةٌ للمتّقين «وزخرفا وإن كل ذلك لما متاع الحياة الدنيا والآخرة عند ربك للمتقين»؛ ففي هذا حصرُ زخرفِ الدنيا في كونه متاعًا زائلًا، وتخصيصُ الآخرةِ للمتّقين؛ فزخرفُ الدنيا كلُّه متاعٌ قليلٌ زائل، لا وزنَ له عند الله؛ والآخرةُ ونعيمها الباقي للمتّقين خاصّة؛ فاطلب الآخرةَ بالتقوى؛ فهي خيرٌ وأبقى من زخرفِ الدنيا؛ فالزخرفُ متاعٌ زائلٌ يعطيه الله البرَّ والفاجر؛ والآخرةُ نعيمٌ باقٍ لا يناله إلا المتّقون؛ فاجعل التقوى زادك إلى الآخرة؛ ولا تؤثر زخرفَ الدنيا الزائلَ على نعيمِ الآخرةِ الباقي؛ فالعاقلُ يعمل للآخرةِ الباقيةِ بالتقوى، لا للدنيا الفانيةِ بالزخرف؛ فمن اتّقى الله نال الآخرة، ومن آثر الزخرفَ خسرها؛ فاطلب الآخرةَ بالتقوى؛ فهي للمتّقين؛ فاعمل عملَ المتّقين لتنالها؛ فالتقوى سبيلُ الآخرة، والزخرفُ متاعٌ زائل."}}]},{"title":"قرينُ السوءِ للمعرض، وتسليةُ النبيّ، والاستمساكُ بالوحي، ووحدةُ دعوةِ الرسل","range":[36,45],"theme":"أنّ من يعرض عن ذكرِ الرحمنِ يُقيَّض له شيطانٌ قرينٌ يصدّه ويحسب أنه مهتد ثم يندم عليه يومَ القيامة، وأنّ اشتراكهم في العذابِ لا ينفعهم، وتسليةُ النبيِّ بأنه لا يُسمِع الصمَّ وأنّ الله منتقمٌ من المكذّبين مقتدرٌ عليهم، والأمرُ بالاستمساكِ بالوحيِ فهو الصراطُ المستقيمُ وذكرٌ يُسأل عنه، وأنّ الرسلَ كلَّهم دعوا إلى التوحيد","verses":[{"n":36,"reflection":{"text":"«ومن يعش عن ذكر الرحمن نقيض له شيطانا فهو له قرين» — ومن يُعرِض ويتعامَ عن ذكرِ الرحمنِ (القرآنِ) نسبّب له شيطانًا يكون قرينًا له؛ ففي هذا بيانُ عقوبةِ الإعراضِ عن الذكرِ بتسليطِ الشيطان؛ فاحذر الإعراضَ عن ذكرِ الله وقرآنه، فإنه يسلّط عليك شيطانًا، فالزم ذكرَ الله لتُعصَم من الشيطان، فالغفلةُ عن الذكرِ تجلب قرينَ السوء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ ذكرِ الله، فالإعراضُ عنه يسلّط قرينَ السوءِ من الشياطين."},"action":{"text":"تأمّل عقوبةَ الإعراضِ عن الذكر: ومن يعشُ ويُعرِض ويتعامَ عن ذكرِ الرحمنِ — القرآنِ والإيمانِ والطاعة — نقيّض ونسبّب له شيطانًا يلازمه، فهو له قرينٌ يزيّن له الباطلَ ويصدّه عن الحق «ومن يعش عن ذكر الرحمن نقيض له شيطانا فهو له قرين»؛ ففي هذا بيانُ أنّ الإعراضَ عن ذكرِ الله عقوبتُه تسليطُ الشيطانِ قرينًا؛ فمن أعرض عن ذكرِ الله سلّط الله عليه شيطانًا يقارنه ويضلّه؛ فاحذر الإعراضَ عن ذكرِ الله وقرآنه وطاعته؛ فإنّ الإعراضَ عن الذكرِ يسلّط عليك شيطانًا قرينًا يزيّن لك الباطلَ ويصدّك عن الحق؛ فالزم ذكرَ الله وقراءةَ القرآنِ والطاعة؛ فبذكرِ الله تُعصَم من الشيطان؛ فالذكرُ حصنٌ من الشيطان؛ ومن قرأ آيةَ الكرسيِّ لم يزل عليه من الله حافظٌ ولا يقربه شيطان؛ فالغفلةُ عن ذكرِ الله تجلب قرينَ السوءِ من الشياطين؛ فاعمر قلبك ولسانك بذكرِ الله؛ واحرص على الأذكارِ والتعوّذات؛ فبها تُحصَّن من الشيطان؛ فمن ذكر الله عُصِم، ومن أعرض عنه سُلّط عليه الشيطان؛ فالزم الذكرَ لتنجو من قرينِ السوء."}},{"n":37,"reflection":{"text":"«وإنهم ليصدونهم عن السبيل ويحسبون أنهم مهتدون» — وإنّ الشياطينَ ليصدّون المعرضين عن سبيلِ الحقّ، والمعرضون يحسبون أنهم مهتدون؛ ففي هذا خطرُ الاغترارِ بالضلالِ وحسبانِه هدى؛ فاحذر أن تُصَدَّ عن الحقِّ وأنت تحسب أنك مهتد، فراقب عملك بميزانِ الوحي، فأخطرُ الضلالِ ما يحسبه صاحبه هدى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الضلالِ الذي يُحسَب هدى، ووزنُ العملِ بميزانِ الوحي."},"action":{"text":"تأمّل خطرَ قرينِ السوءِ من الشياطين: وإنّ الشياطينَ القرناءَ ليصدّون المعرضين عن ذكرِ الله عن سبيلِ الحقِّ والهدى، ويزيّنون لهم الباطل؛ والمعرضون مع ذلك يحسبون ويظنّون أنهم مهتدون على الحق «وإنهم ليصدونهم عن السبيل ويحسبون أنهم مهتدون»؛ ففي هذا بيانُ خطرِ قرينِ السوء، وخطرِ الاغترارِ بالضلالِ وحسبانِه هدى؛ فالشياطينُ تصدّ عن الحقِّ وتزيّن الباطل، حتى يظنّ الضالُّ أنه مهتد؛ فاحذر أن تُصَدَّ عن الحقِّ وأنت تحسب أنك مهتد؛ فأخطرُ الضلالِ ما يحسبه صاحبه هدى؛ قل هل ننبّئكم بالأخسرين أعمالًا الذين ضلّ سعيهم في الحياةِ الدنيا وهم يحسبون أنهم يحسنون صنعًا؛ فراقب عملك واعتقادك بميزانِ الوحيِ والسنّة، لا بظنّك وهواك؛ فقد يزيّن الشيطانُ الباطلَ فيحسبه صاحبه حقًّا؛ فمن اغترّ بعمله وظنّه هدًى وهو ضلالٌ فهو أخسرُ الناس؛ فاطلب من الله أن يريك الحقَّ حقًّا ويرزقك اتّباعه، والباطلَ باطلًا ويرزقك اجتنابه؛ ولا تغترّ بعملك؛ بل زِنه بميزانِ الوحي؛ فمن وزن عمله بالوحيِ نجا من الاغترار، ومن اتّبع ظنّه وهواه ضلّ وهو يحسب أنه مهتد."}},{"n":38,"reflection":{"text":"«حتى إذا جاءنا قال يا ليت بيني وبينك بعد المشرقين فبئس القرين» — حتى إذا جاءنا المعرضُ مع قرينِه يومَ القيامة قال: يا ليت بيني وبينك بُعدَ المشرقِ والمغرب، فبئس القرينُ أنت؛ ففي هذا ندمُ المعرضِ على قرينِ السوء؛ فاحذر قرينَ السوءِ الذي تندم على صحبته يومَ القيامة، فاختر القرينَ الصالح، فقرينُ السوءِ ندامةٌ يومَ القيامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من قرينِ السوء، واختيارُ القرينِ الصالح."},"action":{"text":"تأمّل ندمَ المعرضِ على قرينه: حتى إذا جاءنا هذا المعرضُ عن ذكرِ الله يومَ القيامةِ مع قرينِه من الشياطين، قال متحسّرًا نادمًا: يا ليت بيني وبينك بُعدَ المشرقين — المشرقِ والمغرب — فبئس القرينُ أنت الذي أضللتني «حتى إذا جاءنا قال يا ليت بيني وبينك بعد المشرقين فبئس القرين»؛ ففي هذا بيانُ ندمِ المعرضِ على مقارنةِ قرينِ السوءِ يومَ القيامة؛ فيتمنّى لو لم يكن قد قارنه؛ فاحذر قرينَ السوءِ الذي يضلّك ويصدّك عن الحق، فتندم على صحبته يومَ القيامة؛ فقرينُ السوءِ — من الإنسِ أو الجن — يجرّ صاحبه إلى الهلاك؛ ويوم يعضّ الظالمُ على يديه يقول يا ليتني اتّخذت مع الرسولِ سبيلا يا ويلتى ليتني لم أتّخذ فلانًا خليلا؛ فاختر القرينَ الصالحَ الذي يعينك على الخيرِ ويذكّرك بالله؛ فالمرءُ على دينِ خليله؛ فلينظر أحدكم من يخالل؛ فمثلُ الجليسِ الصالحِ كحاملِ المسك، وجليسِ السوءِ كنافخِ الكير؛ فاحرص على صحبةِ الأخيار؛ واحذر صحبةَ الأشرار؛ فقرينُ الخيرِ يدلّك على الجنّة، وقرينُ السوءِ يوردك النار؛ فمن صاحب الأخيارَ سعد، ومن صاحب الأشرارَ ندم؛ فاختر قرينك بعناية."}},{"n":39,"reflection":{"text":"«ولن ينفعكم اليوم إذ ظلمتم أنكم في العذاب مشتركون» — ولن ينفعكم اليومَ اشتراككم في العذابِ مع قرنائكم، لأنكم ظلمتم؛ ففي هذا أنّ اشتراكَ أهلِ العذابِ لا يخفّفه؛ فاعلم أنّ الاشتراكَ في العذابِ لا يخفّفه ولا ينفع، فلا تتّبع أحدًا في الظلمِ ظنًّا أنّ الاشتراكَ يخفّف، فالعذابُ لا يخفّفه اشتراكٌ ولا كثرة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ الاشتراكَ في العذابِ لا يخفّفه، فلا يُتّبَع أحدٌ في الظلم."},"action":{"text":"تأمّل بيانَ أنّ الاشتراكَ في العذابِ لا ينفع: ولن ينفعكم اليومَ — يومَ القيامة — إذ ظلمتم أنفسكم بالكفرِ والمعاصي، أنكم مشتركون في العذابِ أنتم وقرناؤكم؛ فاشتراككم في العذابِ لا يخفّفه عنكم «ولن ينفعكم اليوم إذ ظلمتم أنكم في العذاب مشتركون»؛ ففي هذا بيانُ أنّ اشتراكَ أهلِ العذابِ في العذابِ لا يخفّفه عنهم؛ فقد يظنّ بعضهم أنّ اشتراكهم في العذابِ يخفّفه، كما يُخفَّف المصابُ إذا كثر المصابون في الدنيا؛ لكن عذابَ الآخرةِ لا يخفّفه اشتراكٌ ولا كثرة؛ فلكلٍّ نصيبه الكاملُ من العذاب؛ فاعلم أنّ الاشتراكَ في العذابِ لا يخفّفه ولا ينفع صاحبه؛ فلا تتّبع أحدًا في الظلمِ والمعصيةِ ظنًّا أنّ الاشتراكَ يخفّف العذاب؛ ولا تقل: أفعل ما يفعله الناس، وأُعذَّب كما يُعذَّبون؛ فإنّ العذابَ لا يخفّفه اشتراكٌ ولا كثرة؛ بل كلٌّ يُعذَّب بذنبه عذابًا كاملًا؛ فلا يغرّنك كثرةُ العصاة؛ ولا تتّبعهم في الظلمِ ظنًّا أنّ الكثرةَ تخفّف؛ فكلٌّ يحمل وزره كاملًا؛ فاحذر الظلمَ والمعصية، ولو اشترك فيها الكثيرون؛ فالنجاةُ في الطاعةِ لا في مشاركةِ العصاة."}},{"n":40,"reflection":{"text":"«أفأنت تسمع الصم أو تهدي العمي ومن كان في ضلال مبين» — أفأنت يا محمدُ تُسمِع الصمَّ أو تهدي العميَ ومن كان في ضلالٍ مبين؟ ففي هذا تسليةُ النبيِّ وبيانُ أنّ الهدايةَ بيدِ الله؛ فاعلم أنّ من أعرض عن الحقِّ كالأصمِّ الأعمى لا تملك هدايته، فابذل الدعوةَ ولا تحزن على من لم يهتدِ، فالهدايةُ بيدِ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنّ الهدايةَ بيدِ الله، وبذلُ الدعوةِ دون حزن."},"action":{"text":"تأمّل تسليةَ الله لنبيّه: أفأنت يا محمدُ تقدر أن تُسمِع الصمَّ الذين لا يسمعون الحقَّ سماعَ قبول؟ أو تهدي العميَ الذين لا يبصرون الحقّ؟ أو تهدي من كان في ضلالٍ واضحٍ بيّن؟ لست بقادرٍ على ذلك، إنما عليك البلاغ «أفأنت تسمع الصم أو تهدي العمي ومن كان في ضلال مبين»؛ ففي هذا تسليةُ النبيِّ ﷺ على إعراضِ المكذّبين، وبيانُ أنّ الهدايةَ بيدِ الله؛ فمن أعرض عن الحقِّ وأصرّ على الضلالِ فهو كالأصمِّ الذي لا يسمع، والأعمى الذي لا يبصر؛ فلا تملك هدايته؛ فالهدايةُ — هدايةُ التوفيقِ والقبول — بيدِ الله وحده؛ إنك لا تهدي من أحببت ولكنّ الله يهدي من يشاء؛ فابذل الدعوةَ والنصحَ والبيانَ لمن حولك؛ ثم لا تحزن على من لم يهتدِ بعد بلوغِ الحجّة؛ فليس عليك هداهم؛ إنما عليك البلاغ، وعلى الله الهداية؛ فلا تذهب نفسك عليهم حسرات؛ فما أنت عليهم بمسيطر؛ فأدِّ ما عليك من الدعوة، ووكِّل أمرَ الهدايةِ إلى الله؛ فمن كتب الله له الهدايةَ اهتدى، ومن أصرّ على الضلالِ فهو كالأصمِّ الأعمى؛ فاجتهد في الدعوة، ولا تحمل نفسك ما لا تطيق."}},{"n":41,"reflection":{"text":"«فإما نذهبن بك فإنا منهم منتقمون» — فإما نذهبنّ بك يا محمدُ (بالموت) فإنا منهم منتقمون؛ ففي هذا وعدُ الله بالانتقامِ من المكذّبين؛ فاعلم أنّ الله منتقمٌ من المكذّبين لا محالة، سواءٌ في حياةِ الرسولِ أم بعده، فاثبت على الحقِّ واثقًا بنصرِ الله وانتقامِه من أعدائه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثقةُ بانتقامِ الله من المكذّبين، والثباتُ على الحق."},"action":{"text":"تأمّل وعدَ الله بالانتقامِ من المكذّبين: فإما نذهبنّ بك يا محمدُ بالموتِ قبل أن نريك عذابهم، فإنا منهم منتقمون لا محالة «فإما نذهبن بك فإنا منهم منتقمون»؛ ففي هذا وعدُ الله بالانتقامِ من المكذّبين المعاندين؛ فسواءٌ توفّى الله نبيَّه قبل نزولِ العذابِ بهم، أو أراه ذلك في حياته، فإنّ الله منتقمٌ منهم لا محالة؛ فاعلم أنّ الله منتقمٌ من المكذّبين المعاندين للحق؛ فوعده بالانتقامِ منهم حقٌّ لا يتخلّف؛ فاثبت على الحقِّ واثقًا بنصرِ الله وانتقامِه من أعدائه؛ فلا يهولنّك تسلّطُ أهلِ الباطلِ حينًا؛ فإنّ الله منتقمٌ منهم؛ فالعاقبةُ للحقِّ وأهله، والانتقامُ من المكذّبين؛ فاصبر على أذاهم، وثق بوعدِ الله؛ فإنّ الله لا يترك المكذّبين المعاندين بلا انتقام؛ فمن كذّب الحقَّ وعاند انتقم الله منه؛ فاثبت على الحق، واصبر، وانتظر انتقامَ الله من أعدائه؛ فالنصرُ للحقِّ، والانتقامُ من المكذّبين، ولو بعد حين."}},{"n":42,"reflection":{"text":"«أو نرينك الذي وعدناهم فإنا عليهم مقتدرون» — أو نرينّك الذي وعدناهم من العذاب في حياتك، فإنا عليهم مقتدرون؛ ففي هذا بيانُ قدرةِ الله على المكذّبين؛ فاعلم أنّ الله مقتدرٌ على المكذّبين، فلا يعجزونه، فاثبت على الحقِّ واثقًا بقدرةِ الله على أعدائه، فالمكذّبون تحت قدرةِ الله لا يفوتونه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بقدرةِ الله على المكذّبين، والثباتُ على الحق."},"action":{"text":"تأمّل بيانَ قدرةِ الله على المكذّبين: أو نرينّك يا محمدُ في حياتك الذي وعدناهم من العذابِ والنكال، فتقرّ عينك بذلك، فإنا عليهم مقتدرون قادرون لا يعجزوننا «أو نرينك الذي وعدناهم فإنا عليهم مقتدرون»؛ ففي هذا بيانُ قدرةِ الله التامّةِ على المكذّبين؛ فهم تحت قدرةِ الله، لا يفوتونه ولا يعجزونه؛ فاعلم أنّ الله مقتدرٌ على المكذّبين المعاندين؛ فلا يعجزونه ولا يفوتونه؛ وما هم بمعجزين؛ فاثبت على الحقِّ واثقًا بقدرةِ الله على أعدائه؛ فلا يهولنّك تسلّطهم؛ فإنهم تحت قدرةِ الله، يأخذهم متى شاء؛ فالله قادرٌ على إهلاكهم والانتقامِ منهم في أيِّ وقتٍ شاء؛ فاصبر، وثق بقدرةِ الله؛ فإنّ المكذّبين مهما تجبّروا فهم تحت قهرِ الله وقدرته؛ فمن ثبت على الحقِّ واثقًا بقدرةِ الله نصره الله؛ فاجعل ثقتك بقدرةِ الله على أعدائه؛ فهو المقتدرُ عليهم، لا يفوتونه؛ فالعاقبةُ للحقِّ، والله مقتدرٌ على المكذّبين."}},{"n":43,"reflection":{"text":"«فاستمسك بالذي أوحي إليك إنك على صراط مستقيم» — فتمسّك بالذي أُوحِي إليك (القرآن)، إنك على صراطٍ مستقيم؛ ففي هذا الأمرُ بالتمسّكِ بالوحيِ والثباتِ عليه؛ فتمسّك بالقرآنِ واعمل به، فمن تمسّك بالوحيِ فهو على صراطٍ مستقيم، فاجعل القرآنَ إمامك ودليلك، فالتمسّكُ به عصمةٌ من الضلال.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التمسّكُ بالوحيِ والعملُ به، فهو الصراطُ المستقيم."},"action":{"text":"تأمّل الأمرَ بالتمسّكِ بالوحي: فاستمسك يا محمدُ بالذي أُوحِي إليك من القرآنِ والدين، وتمسّك به واعمل به وادعُ إليه، إنك على صراطٍ مستقيمٍ موصلٍ إلى الله وإلى جنّته «فاستمسك بالذي أوحي إليك إنك على صراط مستقيم»؛ ففي هذا الأمرُ بالتمسّكِ بالوحيِ والثباتِ عليه، وبيانُ أنّ من تمسّك به على صراطٍ مستقيم؛ فالوحيُ — القرآنُ والسنّة — هو الصراطُ المستقيم؛ فتمسّك بالقرآنِ والوحيِ واعمل به؛ فاعتصموا بحبلِ الله جميعًا؛ ومن يعتصم بالله فقد هُدي إلى صراطٍ مستقيم؛ فمن تمسّك بالوحيِ وعمل به فهو على صراطٍ مستقيمٍ لا يضلّ؛ فاجعل القرآنَ والسنّةَ إمامك ودليلك؛ ولا تلتمس الهدى في غيرهما؛ فالتمسّكُ بالوحيِ عصمةٌ من الضلال؛ تركت فيكم ما إن تمسّكتم به لن تضلّوا: كتابَ الله وسنّةَ رسوله؛ فمن تمسّك بالوحيِ اهتدى، ومن أعرض عنه ضلّ؛ فاستمسك بالقرآنِ والسنّة؛ واعمل بهما، وادعُ إليهما؛ فبالتمسّكِ بالوحيِ تسلك الصراطَ المستقيم؛ فهو حبلُ الله المتين، وصراطُه المستقيم."}},{"n":44,"reflection":{"text":"«وإنه لذكر لك ولقومك وسوف تسألون» — وإنّ القرآنَ لشرفٌ لك ولقومك، وسوف تُسألون عنه؛ ففي هذا بيانُ شرفِ القرآنِ ومسؤوليةِ حمله؛ فاعلم أنّ القرآنَ شرفٌ لمن حمله وعمل به، وأنك مسؤولٌ عنه، فاحمل القرآنَ واعمل به وأدِّ حقّه، فالقرآنُ شرفٌ ومسؤولية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ شرفِ القرآنِ ومسؤوليةِ حمله، والقيامُ بحقّه."},"action":{"text":"تأمّل بيانَ شرفِ القرآنِ ومسؤوليته: وإنّ هذا القرآنَ لذكرٌ وشرفٌ ورفعةٌ لك يا محمدُ ولقومك — العربِ خاصّةً والمسلمين عامّةً؛ وسوف تُسألون عنه يومَ القيامة: هل قمتم بحقّه من الإيمانِ والعملِ والتبليغ؟ «وإنه لذكر لك ولقومك وسوف تسألون»؛ ففي هذا بيانُ شرفِ القرآنِ لحملته، ومسؤوليتهم عنه؛ فالقرآنُ شرفٌ ورفعةٌ لمن حمله وعمل به وبلّغه؛ لقد أنزلنا إليكم كتابًا فيه ذكركم؛ فاعلم أنّ القرآنَ شرفٌ عظيمٌ لمن حمله وعمل به؛ وأنك مسؤولٌ عنه يومَ القيامة؛ فاحمل القرآنَ حقَّ الحمل: بالإيمانِ به، والعملِ بمقتضاه، وتلاوته، وتدبّره، وتبليغه؛ وأدِّ حقّه؛ فالقرآنُ أمانةٌ ومسؤولية؛ وسوف تُسأل عنه: أقمت بحقّه أم ضيّعته؟ فمن قام بحقِّ القرآنِ نال شرفه، ومن ضيّعه خسر؛ فاجعل القرآنَ شرفك بالعملِ به؛ واستعدّ للسؤالِ عنه بالقيامِ بحقّه؛ فالقرآنُ شرفٌ لمن أقام حقّه، ومسؤوليةٌ يُسأل عنها؛ فأدِّ حقّ القرآنِ لتنال شرفه وتسلم من مسؤوليته."}},{"n":45,"reflection":{"text":"«واسأل من أرسلنا من قبلك من رسلنا أجعلنا من دون الرحمن آلهة يعبدون» — واسأل أخبارَ من أرسلنا قبلك من الرسل: أجعلنا من دونِ الرحمنِ آلهةً تُعبَد؟ ففي هذا تقريرُ أنّ دعوةَ الرسلِ كلِّهم التوحيد؛ فاعلم أنّ جميعَ الرسلِ دعوا إلى توحيدِ الله لا إلى الشرك، فالتوحيدُ دينُ الرسلِ جميعًا، فاتّبع ما اتّفق عليه الرسلُ من التوحيد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بأنّ دعوةَ الرسلِ كلِّهم التوحيد، واتّباعُ ما اتّفقوا عليه."},"action":{"text":"تأمّل تقريرَ وحدةِ دعوةِ الرسل: واسأل يا محمدُ أخبارَ من أرسلنا من قبلك من رسلنا، وانظر في شرائعهم ودعوتهم: أجعلنا من دونِ الرحمنِ آلهةً تُعبَد؟ لم يفعلوا؛ بل دعوا كلُّهم إلى توحيدِ الله وحده «واسأل من أرسلنا من قبلك من رسلنا أجعلنا من دون الرحمن آلهة يعبدون»؛ ففي هذا تقريرُ أنّ دعوةَ الرسلِ كلِّهم واحدة: التوحيدُ ونبذُ الشرك؛ فما بعث الله رسولًا إلا بالتوحيد؛ ولقد بعثنا في كلِّ أمّةٍ رسولًا أن اعبدوا الله واجتنبوا الطاغوت؛ وما أرسلنا من قبلك من رسولٍ إلا نوحي إليه أنه لا إله إلا أنا فاعبدون؛ فاعلم أنّ جميعَ الرسلِ من نوحٍ إلى محمدٍ دعوا إلى توحيدِ الله وإخلاصِ العبادةِ له، لا إلى الشرك؛ فالتوحيدُ دينُ الرسلِ جميعًا وأصلُ دعوتهم؛ فاتّبع ما اتّفق عليه الرسلُ كلُّهم من التوحيدِ ونبذِ الشرك؛ فمن اتّبع التوحيدَ فقد اتّبع دينَ الرسلِ جميعًا؛ ومن أشرك فقد خالفهم كلَّهم؛ فحقّق التوحيدَ الذي هو دينُ الرسل؛ فهو الحقُّ الذي اتّفقوا عليه؛ فاتّبعه، ولا تلتفت إلى شبهاتِ المشركين."}}]},{"title":"موسى وفرعونُ واستهزاؤه واغترارُه بملكه، واستخفافُه قومَه، وإغراقُه","range":[46,56],"theme":"إرسالُ موسى بالآياتِ إلى فرعونَ وملئه فاستهزؤوا بها وأُخِذوا بالعذابِ ليرجعوا، ومراوغتُهم بطلبِ الدعاءِ بكشفِ العذابِ ثم نكثِهم، واغترارُ فرعونَ بملكِ مصرَ واحتقارُه موسى بمقاييسِ الدنيا واقتراحُه الأساورَ والملائكة، واستخفافُه قومَه الفاسقين فأطاعوه، فلمّا أغضبوا الله أغرقهم أجمعين وجعلهم سلفًا ومثلًا للآخرين","verses":[{"n":46,"reflection":{"text":"«ولقد أرسلنا موسى بآياتنا إلى فرعون وملئه فقال إني رسول رب العالمين» — ولقد أرسلنا موسى بآياتنا إلى فرعونَ وأشرافِ قومه، فقال: إني رسولُ ربِّ العالمين؛ ففي هذا بيانُ إرسالِ موسى بالتوحيدِ إلى الطغاة؛ فاعتبر بدعوةِ موسى للطغاةِ بالتوحيدِ والشجاعةِ في إبلاغه، فالداعيةُ يبلّغ الحقَّ للطغاةِ بشجاعة، فبلّغ الحقَّ ولو للأقوياء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الشجاعةُ في تبليغِ الحقِّ للطغاة، والاعتبارُ بدعوةِ موسى."},"action":{"text":"تأمّل إرسالَ موسى إلى فرعون: ولقد أرسلنا موسى بآياتنا وحججنا الباهرةِ إلى فرعونَ الطاغيةِ وملئه وأشرافِ قومه؛ فقال لهم موسى بشجاعةٍ وثبات: إني رسولُ ربِّ العالمين إليكم «ولقد أرسلنا موسى بآياتنا إلى فرعون وملئه فقال إني رسول رب العالمين»؛ ففي هذا بيانُ إرسالِ موسى بالتوحيدِ والآياتِ إلى فرعونَ الطاغيةِ وملئه، وشجاعتِه في إبلاغِ الحق؛ فواجه موسى أعتى الطغاةِ بكلمةِ الحق؛ فاعتبر بدعوةِ موسى للطغاةِ بالتوحيد، وشجاعتِه في إبلاغِ الحقِّ لهم؛ فالداعيةُ الصادقُ يبلّغ الحقَّ للطغاةِ والأقوياءِ بشجاعةٍ وثبات، لا يخاف في الله لومةَ لائم؛ اذهبا إلى فرعونَ إنه طغى فقولا له قولًا ليّنًا؛ فبلّغ الحقَّ ولو للأقوياءِ والطغاة؛ ولا يمنعك خوفهم من قولِ الحق؛ فأفضلُ الجهادِ كلمةُ حقٍّ عند سلطانٍ جائر؛ فاقتدِ بموسى في الشجاعةِ في إبلاغِ الحقِّ للطغاة؛ ثم فوّض أمرك إلى الله؛ فمن بلّغ الحقَّ بشجاعةٍ وتوكّل على الله كفاه الله؛ فبلّغ الحقَّ، ولا تخف إلا الله."}},{"n":47,"reflection":{"text":"«فلما جاءهم بآياتنا إذا هم منها يضحكون» — فلمّا جاءهم موسى بآياتنا إذا هم منها يضحكون استهزاءً؛ ففي هذا استهزاءُ الطغاةِ بآياتِ الله؛ فاحذر الاستهزاءَ بآياتِ الله، فالاستهزاءُ بالآياتِ من طبعِ المكذّبين، فعظّم آياتِ الله ولا تستهزئ بها، فالاستهزاءُ بالحقِّ عاقبتُه وخيمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاستهزاءِ بآياتِ الله، وتعظيمُها."},"action":{"text":"تأمّل استهزاءَ فرعونَ وملئه بآياتِ الله: فلمّا جاءهم موسى بآياتنا الواضحاتِ الدالّةِ على صدقه، إذا هم منها يضحكون ويستهزئون، بدلًا من أن يؤمنوا بها «فلما جاءهم بآياتنا إذا هم منها يضحكون»؛ ففي هذا بيانُ استهزاءِ الطغاةِ بآياتِ الله؛ فلمّا رأوا الآياتِ العظيمةَ قابلوها بالضحكِ والاستهزاءِ لا بالإيمانِ والتصديق؛ فاحذر الاستهزاءَ بآياتِ الله وشعائرِه ودينه؛ فالاستهزاءُ بالآياتِ والحقِّ من طبعِ المكذّبين المعاندين؛ وإذا رأوا آيةً يستسخرون؛ فعظّم آياتِ الله — القرآنيةَ والكونية — ولا تستهزئ بها؛ ولا تسخر من شيءٍ من دينِ الله وشعائره؛ فالاستهزاءُ بالحقِّ وآياتِ الله عاقبتُه وخيمة؛ قل أبالله وآياته ورسوله كنتم تستهزئون لا تعتذروا قد كفرتم بعد إيمانكم؛ فالاستهزاءُ بآياتِ الله كفر؛ فعظّم آياتِ الله وشعائره؛ ومن يعظّم شعائرَ الله فإنها من تقوى القلوب؛ فمن عظّم آياتِ الله انتفع بها، ومن استهزأ بها هلك؛ فاجعل قلبك معظّمًا لآياتِ الله، لا مستهزئًا بها."}},{"n":48,"reflection":{"text":"«وما نريهم من آية إلا هي أكبر من أختها وأخذناهم بالعذاب لعلهم يرجعون» — وما نريهم من آيةٍ إلا هي أعظمُ من الأخرى، وأخذناهم بالعذابِ (كالطوفانِ والجراد) لعلّهم يرجعون؛ ففي هذا تتابعُ آياتِ الله وعقوباتِه للرجوع؛ فاعلم أنّ الله يبتلي بالآياتِ والعقوباتِ ليرجع العبدُ إليه، فإذا نزلت بك عقوبةٌ فارجع إلى الله، فالعقوباتُ داعيةٌ للرجوعِ والتوبة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجوعُ إلى الله عند العقوبات، وإدراكُ حكمتِها في الرجوع."},"action":{"text":"تأمّل تتابعَ آياتِ الله وعقوباتِه على فرعونَ وقومه: وما نريهم من آيةٍ من الآياتِ التسعِ إلا هي أكبرُ وأعظمُ من أختها التي قبلها؛ وأخذناهم بالعذابِ — كالطوفانِ والجرادِ والقمّلِ والضفادعِ والدم — لعلّهم يرجعون عن كفرهم وطغيانهم «وما نريهم من آية إلا هي أكبر من أختها وأخذناهم بالعذاب لعلهم يرجعون»؛ ففي هذا بيانُ تتابعِ آياتِ الله وعقوباتِه على المكذّبين، وأنّ حكمتها الرجوعُ إلى الله؛ فأرسل الله عليهم الآياتِ والعقوباتِ المتتابعةَ ليرجعوا؛ فاعلم أنّ الله يبتلي عباده بالآياتِ والعقوباتِ ليرجعوا إليه ويتوبوا؛ ولنذيقنّهم من العذابِ الأدنى دون العذابِ الأكبرِ لعلّهم يرجعون؛ فإذا نزلت بك عقوبةٌ أو بلاءٌ فارجع إلى الله بالتوبةِ والإنابة؛ ولا تُصِرّ على المعصيةِ فتُبتَلى بأعظمَ منها؛ فالعقوباتُ والبلايا داعيةٌ للرجوعِ إلى الله والتوبةِ إليه؛ فمن رجع إلى الله عند العقوبةِ رحمه، ومن أصرّ عوقب بأشدّ؛ فاجعل من العقوباتِ والبلايا داعيًا للرجوعِ إلى الله؛ فبادر بالتوبةِ والرجوعِ عند نزولِ البلاء؛ فالحكمةُ من العقوباتِ الرجوعُ إلى الله."}},{"n":49,"reflection":{"text":"«وقالوا يا أيه الساحر ادع لنا ربك بما عهد عندك إننا لمهتدون» — وقالوا: يا أيها الساحرُ ادعُ لنا ربّك بما عهد عندك (من كشفِ العذابِ إن آمنّا)، إننا لمهتدون؛ ففي هذا مراوغةُ المكذّبين عند العذاب؛ فاحذر الوعودَ الكاذبةَ عند الشدّة، فالمكذّبون يعدون بالإيمانِ عند العذابِ ثم ينكثون، فاصدق مع الله في الرخاءِ والشدّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصدقُ مع الله في الرخاءِ والشدّة، والحذرُ من الوعودِ الكاذبة."},"action":{"text":"تأمّل مراوغةَ فرعونَ وقومه عند العذاب: وقالوا لموسى لمّا نزل بهم العذاب: يا أيها الساحرُ — يخاطبونه بذلك تعظيمًا لعلمه في زعمهم، أو استهزاءً — ادعُ لنا ربّك بما عهد عندك من كشفِ العذابِ إن آمنّا، إننا لمهتدون مؤمنون إن كشفته «وقالوا يا أيه الساحر ادع لنا ربك بما عهد عندك إننا لمهتدون»؛ ففي هذا بيانُ مراوغةِ المكذّبين ووعودهم الكاذبةِ عند نزولِ العذاب؛ فوعدوا بالإيمانِ والاهتداءِ إن كُشِف العذابُ عنهم؛ ولكنهم كاذبون؛ فاحذر الوعودَ الكاذبةَ عند الشدّةِ والعذاب؛ فإنّ المكذّبين يعدون بالإيمانِ والتوبةِ عند نزولِ البلاء، ثم ينكثون ويعودون إذا كُشِف عنهم؛ فلمّا كشفنا عنهم العذابَ إذا هم ينكثون؛ فاصدق مع الله في الرخاءِ والشدّة؛ ولا تكن ممّن يعد الله بالتوبةِ عند الشدّةِ ثم ينكث عند الرخاء؛ فالوفاءُ في العبوديةِ في الحالين؛ فمن صدق مع الله في وعده وفى، ومن كذب نكث؛ فاجعل صدقك مع الله دائمًا، لا وعودًا كاذبةً عند الشدّةِ تُنكَث عند الرخاء؛ فالصادقُ يفي بعهده مع الله في السرّاءِ والضرّاء."}},{"n":50,"reflection":{"text":"«فلما كشفنا عنهم العذاب إذا هم ينكثون» — فلمّا كشفنا عنهم العذابَ إذا هم ينقضون عهدهم ويعودون إلى الكفر؛ ففي هذا نكثُ المكذّبين وعودهم؛ فاحذر نقضَ العهدِ مع الله بعد الفرج، فمن وعد الله بالتوبةِ عند الشدّةِ فليفِ بعد الفرج، فالنكثُ بعد الفرجِ من صفاتِ المكذّبين، فأوفِ بعهدك مع الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الوفاءُ بالعهدِ مع الله بعد الفرج، والحذرُ من النكث."},"action":{"text":"تأمّل نكثَ فرعونَ وقومه: فلمّا كشفنا عنهم العذابَ استجابةً لطلبهم، إذا هم ينكثون وينقضون عهدهم الذي عاهدوا عليه، ويعودون إلى كفرهم وطغيانهم «فلما كشفنا عنهم العذاب إذا هم ينكثون»؛ ففي هذا بيانُ نكثِ المكذّبين لعهودهم بعد كشفِ العذاب؛ فلمّا كُشِف عنهم العذابُ نكثوا ولم يفوا بوعدهم بالإيمان؛ فاحذر نقضَ العهدِ مع الله بعد الفرجِ والنجاة؛ فمن وعد الله بالتوبةِ والطاعةِ عند الشدّةِ والبلاء، فليفِ بعهده بعد الفرجِ والنجاة؛ فالنكثُ بعد الفرجِ من صفاتِ المكذّبين والمنافقين؛ ومنهم من عاهد الله لئن آتانا من فضله لنصّدّقنّ ولنكوننّ من الصالحين فلمّا آتاهم من فضله بخلوا به وتولّوا؛ فأعقبهم نفاقًا في قلوبهم؛ فأوفِ بعهدك مع الله؛ فإذا نجّاك الله من شدّةٍ فاشكره وأوفِ بما وعدت؛ ولا تنكث عهدك بعد الفرج؛ فمن وفى بعهدِ الله أتمّ الله عليه نعمته، ومن نكث عاقبه الله؛ فاجعل الوفاءَ بالعهدِ مع الله دأبك؛ فبادر بالوفاءِ بما عاهدت الله عليه؛ فالوفاءُ بالعهدِ من صفاتِ المؤمنين، والنكثُ من صفاتِ المكذّبين."}},{"n":51,"reflection":{"text":"«ونادى فرعون في قومه قال يا قوم أليس لي ملك مصر وهذه الأنهار تجري من تحتي أفلا تبصرون» — ونادى فرعونُ في قومه: يا قومِ أليس لي ملكُ مصرَ وهذه الأنهارُ تجري من تحتي؟ أفلا تبصرون عظمتي؟ ففي هذا اغترارُ فرعونَ بملكه وطغيانه؛ فاحذر الاغترارَ بالملكِ والمالِ والطغيان، فإنه سببُ الهلاك، فلا تغترّ بما آتاك الله، بل اشكره وتواضع، فالاغترارُ بالنعمةِ يورث الطغيان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاغترارِ بالملكِ والمال، والتواضعُ وشكرُ النعمة."},"action":{"text":"تأمّل اغترارَ فرعونَ بملكه: ونادى فرعونُ في قومه مفتخرًا متكبّرًا: يا قومِ أليس لي ملكُ مصرَ وسلطانها، وهذه الأنهارُ — أنهارُ النيلِ — تجري من تحتِ قصري وبين يديّ؟ أفلا تبصرون عظمتي وملكي، وضعفَ موسى وفقره؟ «ونادى فرعون في قومه قال يا قوم أليس لي ملك مصر وهذه الأنهار تجري من تحتي أفلا تبصرون»؛ ففي هذا بيانُ اغترارِ فرعونَ بملكه وسلطانه وطغيانه؛ فاغترّ بملكه ومالِه حتى تكبّر وطغى واستخفّ بالحقّ؛ فاحذر الاغترارَ بالملكِ والمالِ والجاهِ والسلطان؛ فإنه سببُ الطغيانِ والهلاك؛ كلا إنّ الإنسانَ ليطغى أن رآه استغنى؛ فلا تغترّ بما آتاك الله من نعمةٍ فتطغى وتتكبّر؛ بل اشكر الله على نعمه، وتواضع له؛ واعلم أنّ النعمَ من الله، وأنها زائلة؛ فمن اغترّ بالنعمةِ وطغى بها أهلكه الله؛ ومن شكرها وتواضع بها زاده الله؛ فاجعل نعمَ الله داعيةً للشكرِ والتواضع، لا للطغيانِ والكبر؛ فالاغترارُ بالنعمةِ يورث الطغيانَ والهلاك؛ فتواضع، واشكر، ولا تغترّ."}},{"n":52,"reflection":{"text":"«أم أنا خير من هذا الذي هو مهين ولا يكاد يبين» — أم أنا خيرٌ من موسى الذي هو حقيرٌ ضعيفٌ ولا يكاد يفصح لعقدةٍ في لسانه؟ ففي هذا احتقارُ فرعونَ لموسى بمقاييسِ الدنيا؛ فاحذر احتقارَ أهلِ الحقِّ لفقرهم أو ضعفهم، فالعبرةُ بالحقِّ لا بالمظهر، فلا تزن الناسَ بمقاييسِ الدنيا، فكم من محتقَرٍ خيرٌ عند الله من عظيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ احتقارِ أهلِ الحقّ، ووزنُ الناسِ بالحقِّ لا بالمظهر."},"action":{"text":"تأمّل احتقارَ فرعونَ لموسى: أم أنا خيرٌ من هذا — موسى — الذي هو مهينٌ حقيرٌ ضعيفٌ في زعمه، ولا يكاد يبينُ ويفصح في كلامه لما كان في لسانه من عقدة؟ فاحتقر موسى لفقره وضعفِه الظاهرِ وعقدةِ لسانه «أم أنا خير من هذا الذي هو مهين ولا يكاد يبين»؛ ففي هذا احتقارُ فرعونَ لموسى بمقاييسِ الدنيا: الفقرِ والضعفِ والمظهر؛ فوزن موسى بميزانِ الدنيا لا بميزانِ الحقّ؛ فاحذر احتقارَ أهلِ الحقِّ والدينِ لفقرهم أو ضعفهم أو مظهرهم؛ فالعبرةُ بالحقِّ والتقوى، لا بالمالِ والجاهِ والمظهر؛ فلا تزن الناسَ بمقاييسِ الدنيا؛ فكم من محتقَرٍ عند الناسِ خيرٌ عند الله من عظيمٍ في أعينهم؛ ربّ أشعثَ أغبرَ مدفوعٍ بالأبوابِ لو أقسم على الله لأبرّه؛ فلا تحتقر أحدًا لفقره أو ضعفه أو مظهره؛ فقد يكون أكرمَ عند الله منك؛ فالميزانُ التقوى؛ إنّ أكرمكم عند الله أتقاكم؛ فوزن الناسَ بميزانِ الحقِّ والتقوى؛ فمن وزنهم بالدنيا ضلّ كفرعون، ومن وزنهم بالتقوى اهتدى؛ فلا تحتقر أهلَ الحق، ولا تعظّم أهلَ الدنيا لدنياهم."}},{"n":53,"reflection":{"text":"«فلولا ألقي عليه أسورة من ذهب أو جاء معه الملائكة مقترنين» — فهلّا أُلقِي على موسى أساورُ من ذهبٍ (علامةَ الملك) أو جاء معه الملائكةُ متتابعين يشهدون له؟ ففي هذا اقتراحُ فرعونَ آياتٍ بمقاييسِ الدنيا؛ فاعلم أنّ صدقَ الرسولِ لا يُعرَف بالزينةِ ولا بالمظاهر، بل بالآياتِ والبراهين، فلا تطلب على الحقِّ دلائلَ دنيويّة، فالحقُّ يُعرَف ببرهانه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"معرفةُ الحقِّ ببرهانه، لا بالمظاهرِ والزينةِ الدنيوية."},"action":{"text":"تأمّل اقتراحَ فرعونَ للآياتِ بمقاييسِ الدنيا: فهلّا أُلقِي على موسى — إن كان صادقًا رسولًا كريمًا على ربه — أساورُ وحليٌّ من ذهبٍ علامةً على الملكِ والسيادة؟ أو جاء معه الملائكةُ متتابعين مقترنين يشهدون له بالرسالةِ ويعاونونه؟ فطلب دلائلَ دنيويّةً على صدقِ موسى «فلولا ألقي عليه أسورة من ذهب أو جاء معه الملائكة مقترنين»؛ ففي هذا اقتراحُ فرعونَ آياتٍ بمقاييسِ الدنيا من الحليِّ والزينةِ والأتباع؛ فظنّ أنّ صدقَ الرسولِ يُعرَف بالزينةِ الدنيويّةِ والمظاهر؛ فاعلم أنّ صدقَ الرسولِ لا يُعرَف بالزينةِ والحليِّ والمظاهرِ الدنيوية؛ بل يُعرَف بالآياتِ والبراهينِ الدالّةِ على صدقه؛ وقد جاء موسى بالآياتِ العظيمة؛ فلا تطلب على الحقِّ دلائلَ دنيويّةً من مالٍ أو جاهٍ أو زينة؛ فالحقُّ يُعرَف ببرهانه ودليله، لا بمظهرِ صاحبه؛ فكم من صاحبِ حقٍّ فقيرٍ ضعيفِ المظهر؛ وكم من صاحبِ باطلٍ غنيٍّ مزيّن؛ فلا تزن الحقَّ بالمظاهرِ الدنيوية؛ بل زِنه ببرهانه ودليله؛ فمن طلب على الحقِّ دلائلَ دنيويّةً ضلّ، ومن عرفه ببرهانه اهتدى؛ فاعرف الحقَّ ببرهانه، لا بزينةِ صاحبه ومظهره."}},{"n":54,"reflection":{"text":"«فاستخف قومه فأطاعوه إنهم كانوا قوما فاسقين» — فاستخفّ فرعونُ عقولَ قومه فأطاعوه في الباطل، إنهم كانوا قومًا فاسقين؛ ففي هذا خطرُ اتّباعِ الطغاةِ في الباطل؛ فاحذر أن تُستَخَفَّ عقلك فتتّبع الباطل، فأعمل عقلك ولا تتّبع أحدًا في الباطل، فاتّباعُ الطغاةِ في الباطلِ فسوقٌ وضلال، فلا تكن ممّن يُستَخَفّ فيطيع الباطل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إعمالُ العقلِ وعدمُ اتّباعِ الطغاةِ في الباطل."},"action":{"text":"تأمّل كيف استخفّ فرعونُ قومه: فاستخفّ فرعونُ عقولَ قومه وحملهم على الطيشِ والخفّة، فأطاعوه فيما دعاهم إليه من الباطلِ والكفرِ وتكذيبِ موسى؛ إنهم كانوا قومًا فاسقين خارجين عن طاعةِ الله، فلذلك أطاعوا فرعونَ في الباطل «فاستخف قومه فأطاعوه إنهم كانوا قوما فاسقين»؛ ففي هذا بيانُ خطرِ اتّباعِ الطغاةِ في الباطل، وأنّ الفسوقَ يحمل على طاعتهم؛ فاستخفّ فرعونُ عقولهم فاتّبعوه في الباطل؛ ولم يعملوا عقولهم في تمييزِ الحقِّ من الباطل؛ فاحذر أن تُستَخَفَّ عقلك فتتّبع الباطلَ والطغاةَ فيه؛ فأعمل عقلك في تمييزِ الحقِّ من الباطل؛ ولا تتّبع أحدًا في الباطلِ ولو كان ذا سلطانٍ وجاه؛ فلا طاعةَ لمخلوقٍ في معصيةِ الخالق؛ فاتّباعُ الطغاةِ والمضلّين في الباطلِ فسوقٌ وضلالٌ وهلاك؛ ولاحظ أنّ فسوقهم وخروجهم عن طاعةِ الله هو الذي حملهم على طاعةِ فرعونَ في الباطل؛ فمن فسق عن أمرِ الله سهُل انقياده للباطل؛ فالزم طاعةَ الله؛ وأعمل عقلك؛ ولا تتّبع الطغاةَ والمضلّين في باطلهم؛ فمن أعمل عقله واتّبع الحقَّ نجا، ومن استُخِفّ فأطاع الباطلَ هلك."}},{"n":55,"reflection":{"text":"«فلما آسفونا انتقمنا منهم فأغرقناهم أجمعين» — فلمّا أغضبونا بكفرهم وطغيانهم انتقمنا منهم فأغرقناهم أجمعين؛ ففي هذا عاقبةُ الطغيانِ والإغضابِ لله؛ فاحذر ما يُغضِب الله من الكفرِ والطغيانِ والمعاصي، فإنه سببُ العذاب، فاتّق الله ولا تُغضِبه، فمن أغضب الله بطغيانه انتقم الله منه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ ممّا يُغضِب الله من الطغيانِ والمعاصي."},"action":{"text":"تأمّل عاقبةَ فرعونَ وقومه: فلمّا آسفونا — أي أغضبونا بإصرارهم على الكفرِ والطغيانِ والتكذيب — انتقمنا منهم، فأغرقناهم أجمعين في البحر؛ فرعونَ وجنودَه كلَّهم «فلما آسفونا انتقمنا منهم فأغرقناهم أجمعين»؛ ففي هذا بيانُ عاقبةِ الطغيانِ والإصرارِ على ما يُغضِب الله؛ فلمّا أغضبوا الله بكفرهم وطغيانهم أهلكهم الله جميعًا؛ فاحذر ما يُغضِب الله من الكفرِ والطغيانِ والمعاصي والإصرارِ عليها؛ فإنّ إغضابَ الله سببُ العذابِ والهلاك؛ فاتّق الله، ولا تُغضِبه بمعصيتك وطغيانك؛ فمن أغضب الله بإصراره على المعاصيِ والطغيانِ انتقم الله منه وأهلكه؛ فالمعاصيُ والطغيانُ تُغضِب الله؛ فاجتنبها؛ واطلب رضا الله بطاعته؛ فمن اتّقى الله ورضي عنه نجا، ومن أغضبه بطغيانه هلك؛ فاحذر أسبابَ غضبِ الله؛ والزم أسبابَ رضاه؛ فرضا الله في طاعته، وغضبه في معصيته؛ فبادر بالطاعةِ والتوبة، واجتنب ما يُغضِب الله؛ فمن أغضب الله فقد عرّض نفسه لانتقامه؛ فاطلب رضا الله، واحذر غضبه."}},{"n":56,"reflection":{"text":"«فجعلناهم سلفا ومثلا للآخرين» — فجعلناهم سلفًا متقدّمين في الهلاك، وعبرةً ومثلًا للآخرين يعتبرون بهم؛ ففي هذا أنّ الهالكين عبرةٌ للباقين؛ فاعتبر بمن هلك من الطغاةِ والمكذّبين، فقد جعلهم الله عبرةً لك، فاتّعظ بهم ولا تسلك سبيلهم، فالهالكون عبرةٌ لمن اعتبر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بالهالكين من الطغاة، والاتّعاظُ بهم."},"action":{"text":"تأمّل ختامَ قصّةِ فرعون: فجعلناهم سلفًا — متقدّمين في الكفرِ والهلاكِ يتبعهم أشباههم — ومثلًا وعبرةً للآخرين يعتبرون بهم ويتّعظون بمصيرهم «فجعلناهم سلفا ومثلا للآخرين»؛ ففي هذا بيانُ أنّ الهالكين من الطغاةِ والمكذّبين عبرةٌ ومثلٌ للباقين؛ فجعل الله فرعونَ وقومه عبرةً لمن بعدهم؛ فاعتبر بمن هلك من الطغاةِ والمكذّبين قبلك؛ فقد جعلهم الله عبرةً ومثلًا لك لتتّعظ؛ فسِر في الأرضِ وانظر كيف كان عاقبةُ المكذّبين والطغاة؛ واتّعظ بمصارعهم؛ ولا تسلك سبيلهم في الكفرِ والطغيانِ والتكذيب؛ فمن اعتبر بالهالكين سلم، ومن سلك سبيلهم هلك مثلهم؛ فاجعل من قصصِ الطغاةِ الهالكين عبرةً تحملك على الإيمانِ والتقوى وترْكِ الطغيان؛ فلقد كان في قصصهم عبرةٌ لأولي الألباب؛ فالهالكون عبرةٌ لمن اعتبر، ومثلٌ لمن اتّعظ؛ فكن ممّن يعتبر بهم ويتّعظ بمصيرهم؛ فبالاعتبارِ بالهالكين تنجو من مصيرهم؛ فاتّعظ، ولا تكن مثلَ الطغاةِ الهالكين."}}]}],"coverage":{"covered":56,"total":89}};
